insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-00-the-fool', 'The Fool', 'major', null, 0, '{"keywords":{"upright":["beginnings","openness","spontaneity","trust","a leap of faith"],"reversed":["recklessness","hesitation","naivety","carelessness"]},"traditional":"Waite lists folly, extravagance and frenzy for the upright card, and negligence, carelessness and apathy reversed; in his symbolic description the Fool is the spirit setting out in search of experience.","symbols":[{"element":"The cliff edge","meaning":"The threshold of the unknown: the next step cannot be seen, only taken."},{"element":"The white rose","meaning":"Innocence and a pure motive carried into the journey."},{"element":"The small bundle","meaning":"Everything the traveller needs is light and already with them; past baggage has been left behind."},{"element":"The white dog","meaning":"Instinct and loyal companionship, either warning of the edge or urging the traveller on."},{"element":"The sun and open sky","meaning":"A bright, unclouded beginning and a sense of possibility."}],"upright":"A fresh start asks for curiosity more than certainty. The Fool invites you to begin before you feel fully ready and to treat not-knowing as part of the adventure.","reversed":"Either the leap is being made without looking, or fear is stopping a step that is genuinely yours to take. Check whether you are being careless or merely cautious.","contexts":{"love":"Approach connection with openness and playfulness rather than a script; a new relationship or a new way of relating can begin here.","career":"A new role, project or field is calling; enthusiasm is an asset, but pair it with a little research.","finances":"Fresh starts with money are possible, but impulsive spending or untested ventures need a safety net.","family":"A household change or new chapter may feel unfamiliar; lightness and curiosity help everyone adjust.","growth":"You are being asked to try something as a beginner and to let go of needing to look competent."},"shadow":"Freedom can become avoidance: drifting from commitment to commitment so nothing has to be finished.","misconceptions":["The Fool does not mean the querent is foolish; it describes the innocent, open state of a beginner.","Despite being numbered 0, it is not ''nothing'' — zero is the potential that precedes the whole journey."],"example":"Someone asking whether to join a pottery class after years of only doing work-related learning draws The Fool: the card encourages enrolling for the joy of it, without demanding a clear purpose.","reflection":["Where in my life am I waiting to feel ready before beginning?","What would I try if I allowed myself to be a beginner?"],"memoryAid":"Zero baggage, full sky: the Fool travels light toward the unknown.","action":"Take one small, low-risk first step toward something new today, without planning the whole route.","related":[{"id":"major-01-the-magician","reason":"The next step of the journey: potential turns into deliberate skill."},{"id":"major-21-the-world","reason":"The journey''s completion, after which the Fool begins again."},{"id":"wands-01-ace","reason":"Shares the spark of a new beginning, focused through action."}],"numeral":"0","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-01-the-magician', 'The Magician', 'major', null, 1, '{"keywords":{"upright":["skill","willpower","focus","resourcefulness","manifestation"],"reversed":["manipulation","scattered energy","untapped talent","trickery"]},"traditional":"Waite gives skill, diplomacy, subtlety, self-confidence and will for the upright card; reversed he names the physician or magus in a negative sense, disgrace and disquiet.","symbols":[{"element":"Wand raised, hand pointing down","meaning":"''As above, so below'': the Magician channels inspiration into the material world."},{"element":"The four suit tools on the table","meaning":"Wand, cup, sword and pentacle — every resource needed is already present."},{"element":"The infinity sign","meaning":"Limitless potential and the continuous flow of energy and will."},{"element":"The serpent belt","meaning":"A snake eating its tail: renewal and the eternal cycle."},{"element":"Roses and lilies","meaning":"Desire and pure thought cultivated together in the garden."}],"upright":"You have the tools, the skills and the focus to make something real. The Magician asks you to act deliberately and to align intention with concrete steps.","reversed":"Energy is scattered, talent is going unused, or skill is being used to persuade rather than to serve. Check whether someone — possibly you — is overselling.","contexts":{"love":"Clear, honest communication of what you want can shift a relationship; beware charm that is used as a tactic.","career":"A strong moment to pitch, present, launch or demonstrate competence; gather your resources and act.","finances":"Resourcefulness can turn what you already have into opportunity; be wary of schemes promising effortless gain.","family":"You may be the one who can coordinate or fix a practical problem at home by organising what is available.","growth":"Notice the abilities you already possess instead of waiting for new ones; practise a skill with intent."},"shadow":"Mastery without integrity becomes manipulation: performing confidence to control outcomes or people.","misconceptions":["The Magician is not about literal magic; it describes focused will and the skilful use of resources.","It does not promise success automatically — it shows the capacity to act, which still requires action."],"example":"Someone asking how to approach a job interview draws The Magician: the card points to preparing concrete examples of their skills and presenting them with confidence.","reflection":["Which of my resources am I overlooking right now?","Where would focused effort make the biggest difference this week?"],"memoryAid":"One hand to the sky, one to the ground: the Magician connects idea and action.","action":"List the four resources you have for your current goal — energy, feeling, thinking, material — and use one deliberately today.","related":[{"id":"major-00-the-fool","reason":"The open potential the Magician learns to direct."},{"id":"major-02-the-high-priestess","reason":"Her receptive inner knowing balances his outward action."},{"id":"pentacles-08-eight","reason":"Skill developed through practical, repeated effort."}],"numeral":"I","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-02-the-high-priestess', 'The High Priestess', 'major', null, 2, '{"keywords":{"upright":["intuition","inner knowing","mystery","stillness","the unconscious"],"reversed":["secrets","disconnection from intuition","surface knowledge","withdrawal"]},"traditional":"Waite associates the upright card with secrets, mystery, the future not yet revealed, silence and wisdom; reversed with passion, conceit and surface knowledge.","symbols":[{"element":"The dark and pale pillars","meaning":"Marked B and J, they suggest duality — severity and mercy, unknown and known — with the Priestess seated at the balance point."},{"element":"The pomegranate veil","meaning":"A threshold to hidden knowledge; what lies behind is glimpsed but not handed over."},{"element":"The half-hidden scroll","meaning":"Sacred or secret law, only partly revealed."},{"element":"The crescent moon and lunar crown","meaning":"Cycles, reflection and the intuitive, receptive mind."},{"element":"Still water beyond the veil","meaning":"The depths of the unconscious, calm on the surface."}],"upright":"The answer may not come from more information but from quiet attention. The High Priestess invites patience, listening and trust in what you sense but cannot yet explain.","reversed":"You may be ignoring an inner signal, or something is being kept hidden. It can also mean relying on surface facts while avoiding a deeper truth.","contexts":{"love":"Not everything is spoken yet; give the relationship space and notice what you sense rather than forcing disclosure.","career":"Hold your counsel, observe before acting, and trust your read of a situation that others have not noticed yet.","finances":"Wait for fuller information before committing; hidden terms or details deserve a careful look.","family":"Quiet presence may help more than advice; some family matters unfold only when no one pushes.","growth":"Make room for stillness — meditation, journaling, dreams — to hear what you already know."},"shadow":"Silence can become secrecy or aloofness, withholding from others to keep control.","misconceptions":["She is not passive or powerless; her stillness is an active, attentive form of knowing.","The card does not reveal a specific secret about another person — it asks you to attend to what is hidden from you, including within yourself."],"example":"Someone torn between two job offers draws The High Priestess: rather than another spreadsheet, the card suggests sitting quietly with each option and noticing their bodily response.","reflection":["What do I already sense about this situation that I haven''t admitted?","Where would patience serve me better than action?"],"memoryAid":"Between the pillars, behind the veil: she knows, and she waits.","action":"Spend ten minutes in silence with your question today and write down the first impression that surfaces.","related":[{"id":"major-01-the-magician","reason":"Active will paired with her receptive wisdom."},{"id":"major-18-the-moon","reason":"Both explore intuition and the unconscious; the Moon adds uncertainty and illusion."},{"id":"cups-13-queen","reason":"Shares emotional depth and intuitive perception."}],"numeral":"II","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-03-the-empress', 'The Empress', 'major', null, 3, '{"keywords":{"upright":["abundance","nurturing","fertility","creativity","sensuality"],"reversed":["creative block","dependence","neglect of self","smothering"]},"traditional":"Waite lists fruitfulness, action, initiative and length of days for the upright card, with difficulty and doubt also possible; reversed he gives light, truth and the unravelling of involved matters, and vacillation.","symbols":[{"element":"Crown of twelve stars","meaning":"Connection to the cycles of the year and the celestial order."},{"element":"Ripening wheat","meaning":"Harvest and the reward of patient growth."},{"element":"Venus shield","meaning":"Love, beauty and the creative feminine principle."},{"element":"Pomegranate robe","meaning":"Fertility and abundance, linking her to the High Priestess''s veil."},{"element":"Forest and waterfall","meaning":"Life flowing freely; nature as nourishment."}],"upright":"Growth comes through care, pleasure and patience. The Empress invites you to nourish what you love — a project, a relationship, your own body — and let it flourish in its own time.","reversed":"Care may be flowing in only one direction, or creativity feels blocked. Consider whether you are neglecting yourself or over-mothering something that needs room.","contexts":{"love":"Warmth, affection and attentive care can deepen a bond; enjoy the relationship rather than managing it.","career":"Creative work and projects that need nurturing are favoured; growth may be gradual but genuine.","finances":"A sense of plenty is possible through steady cultivation; enjoy comforts without overspending.","family":"Caretaking is central — of children, parents or the home — and so is receiving care in return.","growth":"Reconnect with your senses, with nature and with making things for pleasure."},"shadow":"Nurture can become control or self-erasure: giving so much that you disappear, or holding on too tightly.","misconceptions":["The Empress is not only about pregnancy or motherhood; she represents creative abundance in any form.","It is not limited to women — anyone can embody nurturing creativity."],"example":"Someone asking how to revive a stalled novel draws The Empress: the card suggests writing for pleasure in a beautiful setting rather than forcing a deadline.","reflection":["What in my life is ready to grow if I tend it?","How am I nourishing myself this week?"],"memoryAid":"The Empress is the garden in full bloom: tend it and it feeds you.","action":"Do one thing purely for sensory pleasure or care today — cook, walk outdoors, tend a plant — and notice its effect.","related":[{"id":"major-04-the-emperor","reason":"Her nurturing abundance is complemented by his structure."},{"id":"pentacles-09-nine","reason":"Shares self-sufficient abundance enjoyed in a garden."},{"id":"pentacles-13-queen","reason":"Practical, earthly nurturing in the suit of Pentacles."}],"numeral":"III","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-04-the-emperor', 'The Emperor', 'major', null, 4, '{"keywords":{"upright":["structure","authority","stability","leadership","protection"],"reversed":["rigidity","domination","lack of discipline","misused power"]},"traditional":"Waite gives stability, power, protection, realisation, reason and conviction for the upright card; reversed, benevolence and compassion but also obstruction and immaturity.","symbols":[{"element":"Stone throne with ram heads","meaning":"Aries energy: initiative, assertion and solid, lasting authority."},{"element":"Armour beneath the robe","meaning":"Readiness to defend what has been built."},{"element":"Ankh sceptre and orb","meaning":"Rule over life and the world: responsibility for the realm."},{"element":"Barren mountains","meaning":"Hard-won order imposed on a demanding landscape."}],"upright":"Clear structure, boundaries and responsible leadership create the stability you need. The Emperor asks you to take charge, make rules that serve, and follow through.","reversed":"Structure has become rigid or controlling — or it is missing entirely. Consider whether authority, yours or someone else''s, is protecting or dominating.","contexts":{"love":"Reliability and clear commitments support the relationship; watch for one partner controlling the other.","career":"Leadership, organisation and accountability are needed; a good time to set systems and expectations.","finances":"Budgets, plans and disciplined management build security.","family":"Someone needs to provide structure and protection; healthy boundaries make the household feel safe.","growth":"Self-discipline and routines turn intentions into results; become the steady authority in your own life."},"shadow":"Order can harden into tyranny: insisting on control because uncertainty feels unbearable.","misconceptions":["The Emperor is not inherently oppressive; healthy authority protects and enables.","It does not always represent a father or a man — it describes a function of structure and leadership."],"example":"Someone overwhelmed by freelance chaos draws The Emperor: the card suggests setting fixed working hours, a simple invoicing system and clear client boundaries.","reflection":["Where do I need firmer structure or boundaries?","Is my need for control serving me or limiting me?"],"memoryAid":"Rams on a stone throne: the Emperor builds order that lasts.","action":"Create one simple rule or routine that would bring order to the area of life that feels most chaotic.","related":[{"id":"major-03-the-empress","reason":"His structure balances her creative abundance."},{"id":"major-05-the-hierophant","reason":"Worldly authority followed by spiritual and traditional authority."},{"id":"wands-14-king","reason":"Visionary leadership in the suit of Wands."}],"numeral":"IV","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-05-the-hierophant', 'The Hierophant', 'major', null, 5, '{"keywords":{"upright":["tradition","teaching","shared beliefs","institutions","mentorship"],"reversed":["unconventionality","challenging dogma","rigid conformity","personal beliefs"]},"traditional":"Waite lists marriage, alliance, captivity and servitude, as well as mercy, goodness and inspiration, for the upright card; reversed, society, concord, over-kindness and weakness.","symbols":[{"element":"Triple crown and triple cross","meaning":"Authority across several levels of existence; the keeper of a spiritual tradition."},{"element":"Hand raised in blessing","meaning":"Knowledge passed on through recognised ritual and teaching."},{"element":"Crossed keys","meaning":"Access to hidden or sacred knowledge, held by the institution."},{"element":"Two kneeling acolytes","meaning":"Students receiving instruction; learning within a lineage."},{"element":"Grey pillars","meaning":"The formal structure of the temple or institution."}],"upright":"Learning from a tradition, teacher or community can guide you now. The Hierophant asks what established wisdom offers and where belonging to a shared practice could help.","reversed":"Conventional answers may not fit. It can signal questioning inherited rules, finding your own path — or, conversely, conforming out of fear.","contexts":{"love":"Shared values and commitments matter; conventional milestones or family expectations may be in focus.","career":"Formal training, institutions, credentials or a mentor can help; follow established procedures.","finances":"Conventional, well-tested approaches are wiser than speculation; seek qualified advice.","family":"Traditions, rituals and inherited values shape the situation; honour them or consciously renegotiate them.","growth":"Study with a teacher or within a tradition — then decide which beliefs are truly your own."},"shadow":"Tradition can become dogma, where belonging requires silencing your own conscience.","misconceptions":["The card is not exclusively religious; it covers any formal system of learning or shared belief.","Reversed does not automatically mean rebellion is right — it asks you to examine your relationship to convention."],"example":"Someone teaching themselves to code draws The Hierophant: the card suggests joining a structured course or finding a mentor rather than continuing alone.","reflection":["Which teachings or traditions genuinely support me?","What beliefs have I inherited without examining?"],"memoryAid":"Keys at his feet, students before him: the Hierophant hands down what was learned.","action":"Seek out one trusted teacher, text or community practice relevant to your question this week.","related":[{"id":"major-02-the-high-priestess","reason":"Hidden, inner wisdom versus taught, outer tradition."},{"id":"pentacles-03-three","reason":"Collaborative learning within an established craft."},{"id":"major-04-the-emperor","reason":"Temporal authority alongside his spiritual authority."}],"numeral":"V","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-06-the-lovers', 'The Lovers', 'major', null, 6, '{"keywords":{"upright":["love","union","values-based choice","harmony","alignment"],"reversed":["disharmony","misaligned values","avoidance of choice","imbalance"]},"traditional":"Waite gives attraction, love, beauty and trials overcome for the upright card, and failure and foolish designs reversed.","symbols":[{"element":"The angel above","meaning":"A higher blessing or principle presiding over the union; often linked to healing."},{"element":"The two figures","meaning":"Two people, or two parts of the self, meeting in openness and honesty."},{"element":"Tree with serpent and fruit","meaning":"Desire, temptation and the knowledge that comes from choice."},{"element":"Tree of flames","meaning":"Passion and spiritual energy."},{"element":"The mountain between them","meaning":"A shared aspiration — or the challenge they must face together."}],"upright":"A meaningful union or a choice rooted in your values is at hand. The Lovers asks you to choose wholeheartedly what you truly value, not what is merely convenient.","reversed":"Something is out of alignment: values clash, communication falters, or a decision is being avoided. Look at where you are divided within yourself.","contexts":{"love":"Deep connection and mutual choice are highlighted; the question is whether both people''s values align.","career":"A partnership or decision that must reflect your values; choose work you can fully commit to.","finances":"Joint finances or a values-based choice about money; be honest about shared priorities.","family":"Harmony depends on honest communication about what each person truly wants.","growth":"Integrate opposing parts of yourself; choose in line with who you want to become."},"shadow":"Romantic idealisation can mask avoidance of a real decision or of incompatibilities.","misconceptions":["The Lovers is not only about romance; at its core it is about choice and alignment of values.","It does not guarantee that a specific person feels a certain way or will become your partner."],"example":"Someone deciding whether to move abroad with a partner draws The Lovers: the card points to an honest conversation about what each of them values in the move.","reflection":["What do I truly value in this situation?","Where am I avoiding a choice by keeping all options open?"],"memoryAid":"Two figures, one blessing: the Lovers choose with the heart and the values aligned.","action":"Write down your top three values for this situation and check whether your current choice honours them.","related":[{"id":"cups-02-two","reason":"Mutual attraction and partnership on the emotional plane."},{"id":"major-15-the-devil","reason":"Mirrors the Lovers'' composition, showing attachment without free choice."},{"id":"major-14-temperance","reason":"Another angelic card concerned with blending and balance."}],"numeral":"VI","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-07-the-chariot', 'The Chariot', 'major', null, 7, '{"keywords":{"upright":["willpower","determination","direction","victory","self-mastery"],"reversed":["loss of direction","scattered effort","aggression","lack of control"]},"traditional":"Waite lists succour, providence, triumph, presumption and trouble for the upright card; reversed, riot, quarrel, dispute and defeat.","symbols":[{"element":"Black and white sphinxes","meaning":"Opposing forces that must be steered together by will rather than reins."},{"element":"No reins","meaning":"Control comes from inner discipline, not force."},{"element":"Starry canopy","meaning":"Celestial guidance and the charioteer''s higher purpose."},{"element":"Armour and crescent moons","meaning":"Protection and emotional defences for the journey."},{"element":"The city behind","meaning":"Leaving the familiar to pursue a goal."}],"upright":"Focused determination carries you forward. The Chariot asks you to harness competing impulses toward one clear direction and keep going.","reversed":"You may be pulled in opposite directions, pushing too hard, or unsure of the destination. Pause to reclaim direction before forcing progress.","contexts":{"love":"Progress requires both people moving in the same direction; avoid trying to ''win'' the relationship.","career":"Drive and discipline bring success against competition; set a clear target and commit.","finances":"Steady, focused effort toward a specific financial goal pays off.","family":"Someone must steer conflicting needs toward a shared plan without steamrolling others.","growth":"Master your impulses; use determination to move through obstacles rather than around them."},"shadow":"Determination becomes domination: winning at all costs or refusing to change course.","misconceptions":["The Chariot does not always mean literal travel or vehicles, though it can.","Victory here is earned through self-control; it is not guaranteed luck."],"example":"Someone training for a marathon while managing a busy job draws The Chariot: the card highlights a disciplined schedule that unites both commitments.","reflection":["What two forces in me need to pull in the same direction?","What exactly is my destination?"],"memoryAid":"Two sphinxes, no reins: the Chariot steers by will alone.","action":"Name one concrete goal and the single next action that moves you toward it — then do it today.","related":[{"id":"major-08-strength","reason":"Strength tames with gentleness where the Chariot directs with will."},{"id":"wands-06-six","reason":"Victory and public recognition after effort."},{"id":"swords-12-knight","reason":"Driven forward motion — sometimes too fast."}],"numeral":"VII","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-08-strength', 'Strength', 'major', null, 8, '{"keywords":{"upright":["courage","compassion","gentle strength","patience","inner resilience"],"reversed":["self-doubt","insecurity","raw emotion","forcefulness"]},"traditional":"Waite gives power, energy, action, courage, magnanimity and complete success for the upright card; reversed, despotism, abuse of power, weakness and discord. (Waite placed Strength at VIII, exchanging it with Justice.)","symbols":[{"element":"The woman closing the lion''s jaws","meaning":"Instinct and passion mastered through gentleness, not violence."},{"element":"The infinity sign","meaning":"The same limitless energy seen above the Magician, now expressed as patient power."},{"element":"The flower garland","meaning":"Beauty and nature binding wild force softly."},{"element":"The calm lion","meaning":"Desire, anger or fear that has been befriended rather than defeated."}],"upright":"True strength is patient, compassionate and steady. This card asks you to meet fear or strong emotion with calm courage instead of force.","reversed":"Self-doubt or overwhelming emotion may be in charge. Alternatively, you may be trying to dominate something that needs gentleness.","contexts":{"love":"Patience and kindness, especially in tense moments, strengthen trust; gentleness is not weakness.","career":"Quiet confidence and emotional steadiness earn respect; handle difficult people with composure.","finances":"Resist impulsive reactions; steady self-control protects your resources.","family":"Compassionate firmness helps — especially with children or anyone acting out of fear.","growth":"Befriend your instincts and emotions rather than suppressing them; courage grows with practice."},"shadow":"Endurance can turn into suppressing your own needs to keep the peace.","misconceptions":["Strength is not about physical power or aggression.","In some decks this card is numbered XI; Waite''s numbering places it at VIII. Both conventions are valid."],"example":"Someone dreading a difficult conversation with a sibling draws Strength: the card suggests going in calmly, listening first and holding their position without hostility.","reflection":["What strong feeling in me needs gentle handling rather than control?","Where have I already shown quiet courage?"],"memoryAid":"A gentle hand on the lion''s jaw: Strength wins by kindness.","action":"When a strong reaction arises today, take three slow breaths before responding.","related":[{"id":"major-07-the-chariot","reason":"Will directed outward versus courage directed inward."},{"id":"wands-09-nine","reason":"Resilience and persistence under pressure."},{"id":"major-11-justice","reason":"The card Waite swapped in numbering with Strength."}],"numeral":"VIII","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-09-the-hermit', 'The Hermit', 'major', null, 9, '{"keywords":{"upright":["introspection","solitude","inner guidance","wisdom","searching"],"reversed":["isolation","loneliness","withdrawal","avoiding reflection"]},"traditional":"Waite lists prudence and circumspection, but also dissimulation and corruption, for the upright card; reversed, concealment, disguise, fear and unreasoned caution.","symbols":[{"element":"The lantern with a six-pointed star","meaning":"Inner wisdom that lights only the next step."},{"element":"The mountain peak","meaning":"Hard-won perspective achieved through effort and solitude."},{"element":"The staff","meaning":"Support, patience and steady progress on the path."},{"element":"The grey cloak","meaning":"Humility and withdrawal from worldly attention."}],"upright":"Step back from noise to find your own answers. The Hermit invites solitude, reflection and seeking guidance from within — or from a wise mentor.","reversed":"Solitude may have become isolation, or you may be avoiding the reflection you need. Consider whether it is time to come down the mountain and reconnect.","contexts":{"love":"Time alone to understand your own needs may be necessary before or within a relationship.","career":"Deep, focused, independent work or a period of reassessing your direction is favoured.","finances":"Review your finances quietly and carefully before making decisions.","family":"Someone may need space; respecting solitude can preserve closeness.","growth":"Retreat, contemplation and study lead to authentic insight."},"shadow":"Wisdom can become aloofness — withdrawing so that no one can challenge or reach you.","misconceptions":["The Hermit does not predict permanent loneliness; solitude is chosen and purposeful.","It does not always mean physically being alone — it can be an inner withdrawal for reflection."],"example":"Someone feeling lost after graduating draws The Hermit: the card suggests a reflective period of journaling and conversations with a mentor before committing to a path.","reflection":["What answer might I hear if the world were quieter?","Is my solitude nourishing me or hiding me?"],"memoryAid":"A lantern on the mountain: the Hermit lights one step at a time.","action":"Schedule thirty minutes of uninterrupted solitude this week to reflect on your question.","related":[{"id":"major-02-the-high-priestess","reason":"Both turn inward; the Hermit actively seeks while she receives."},{"id":"swords-04-four","reason":"Rest and retreat for recovery and clarity."},{"id":"cups-08-eight","reason":"Walking away from the familiar in search of deeper meaning."}],"numeral":"IX","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-10-wheel-of-fortune', 'Wheel of Fortune', 'major', null, 10, '{"keywords":{"upright":["cycles","change","turning points","fortune","timing"],"reversed":["resistance to change","setbacks","feeling out of control","repeating patterns"]},"traditional":"Waite gives destiny, fortune, success, elevation and luck for the upright card; reversed, increase, abundance and superfluity.","symbols":[{"element":"The great wheel","meaning":"The ceaseless turning of fortune, seasons and life cycles."},{"element":"Sphinx with sword","meaning":"Wisdom and balance presiding over change."},{"element":"Serpent descending","meaning":"The downward phase of the cycle — descent into matter or difficulty."},{"element":"Jackal-headed figure rising","meaning":"The upward phase — rising fortunes and renewal."},{"element":"Four winged creatures reading","meaning":"The fixed signs of the zodiac and the elements: stability and learning amid change."}],"upright":"Circumstances are turning. The Wheel invites you to recognise cycles, adapt to change and make the most of a moment of momentum.","reversed":"Change may feel like a setback, or you may be resisting a cycle that needs to turn. Look for the pattern you keep repeating.","contexts":{"love":"A relationship may be entering a new phase; flexibility helps you meet it.","career":"Unexpected opportunities or shifts; timing matters, so be ready to act.","finances":"Finances move in cycles; prepare for downturns in good times and stay steady in lean ones.","family":"Life-stage changes — births, moves, ageing — are reshaping family roles.","growth":"Notice recurring patterns in your life and what they are teaching you."},"shadow":"Believing everything is fate can become a reason to avoid responsibility for your choices.","misconceptions":["The Wheel does not mean luck is guaranteed; it describes change, which can bring ups or downs.","It does not mean your choices are irrelevant — how you respond to change still matters."],"example":"Someone whose company announced a restructure draws the Wheel of Fortune: the card suggests treating the change as a turning point and preparing for new opportunities.","reflection":["What cycle in my life is turning right now?","What pattern keeps returning, and what is it asking of me?"],"memoryAid":"What rises falls and what falls rises: the Wheel keeps turning.","action":"Identify one pattern that repeats in your life and write down one way to respond differently next time.","related":[{"id":"major-21-the-world","reason":"Shares the four creatures in its corners; completion of a cycle."},{"id":"major-11-justice","reason":"Fortune balanced by the consequences of choices."},{"id":"pentacles-02-two","reason":"Adapting gracefully to fluctuating circumstances."}],"numeral":"X","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-11-justice', 'Justice', 'major', null, 11, '{"keywords":{"upright":["fairness","truth","accountability","cause and effect","clarity"],"reversed":["unfairness","dishonesty","avoiding accountability","bias"]},"traditional":"Waite lists equity, rightness, probity and the triumph of the deserving side in law for the upright card; reversed, legal complications, bias and excessive severity.","symbols":[{"element":"The upright double-edged sword","meaning":"Clear, impartial decision that cuts both ways."},{"element":"The balanced scales","meaning":"Weighing evidence and outcomes fairly."},{"element":"The pillars and veil","meaning":"A formal threshold of judgement, echoing the High Priestess."},{"element":"The visible white shoe","meaning":"Readiness to act on a decision once it is made."}],"upright":"Honesty and fairness lead the way. Justice asks you to look clearly at the facts, take responsibility for your part and make a balanced decision.","reversed":"Something feels unfair, or accountability is being avoided. Check your own biases as well as others'' before judging.","contexts":{"love":"Fairness and honest reciprocity matter; address imbalances directly.","career":"Contracts, decisions and evaluations should be handled transparently; integrity is noticed.","finances":"Read the fine print, settle debts and keep accurate records.","family":"Fair distribution of responsibility and honest conversations restore balance.","growth":"Own the consequences of your choices; align actions with your principles."},"shadow":"Judgement can harden into self-righteousness or harshness without compassion.","misconceptions":["Justice does not guarantee winning a legal case; it emphasises fair process and consequences.","Numbering differs between traditions: Waite places Justice at XI; older Marseille-style decks place it at VIII."],"example":"Someone unsure whether to report a billing error in their favour draws Justice: the card points toward honesty and correcting the record.","reflection":["What are the facts here, separate from my feelings about them?","What is my part in this situation?"],"memoryAid":"Sword up, scales level: Justice weighs truly and cuts cleanly.","action":"Write down both sides of a decision you are facing as fairly as you can, then choose.","related":[{"id":"swords-14-king","reason":"Clear, principled judgement in the suit of Swords."},{"id":"major-20-judgement","reason":"Final evaluation and accountability on a larger scale."},{"id":"major-08-strength","reason":"The card exchanged with Justice in Waite''s numbering."}],"numeral":"XI","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-12-the-hanged-man', 'The Hanged Man', 'major', null, 12, '{"keywords":{"upright":["surrender","pause","new perspective","letting go","suspension"],"reversed":["stalling","resistance","needless sacrifice","indecision"]},"traditional":"Waite gives wisdom, circumspection, discernment, trials, sacrifice and intuition for the upright card; reversed, selfishness and the crowd.","symbols":[{"element":"Hanging upside down by one foot","meaning":"A voluntary reversal of perspective; seeing the world differently."},{"element":"The halo","meaning":"Insight and illumination that come from surrender."},{"element":"The living T-shaped tree","meaning":"Growth and life continuing even during suspension."},{"element":"Crossed leg","meaning":"A deliberate, composed posture — this is acceptance, not punishment."}],"upright":"Progress comes from pausing and seeing things differently. The Hanged Man invites you to let go of forcing an outcome and allow a new perspective to emerge.","reversed":"You may be stuck in limbo, resisting a necessary pause, or sacrificing without purpose. Ask what you are waiting for.","contexts":{"love":"Stop pushing for resolution; viewing the relationship from your partner''s perspective may reveal something new.","career":"A delay or pause can be used to rethink your approach rather than forcing progress.","finances":"Hold off on major moves; reassess priorities before committing money.","family":"Letting go of being right can shift a stuck dynamic.","growth":"Surrender control and see what the pause teaches you."},"shadow":"Waiting can become martyrdom or a way of avoiding decisions indefinitely.","misconceptions":["The Hanged Man is not about punishment or literal hanging; the figure is serene.","It does not mean nothing is happening — inner change often occurs during outer stillness."],"example":"Someone frustrated that a house sale has stalled draws The Hanged Man: the card suggests using the pause to reconsider whether this move is still the right one.","reflection":["What would change if I looked at this from the opposite angle?","What am I trying to force that might need to be released?"],"memoryAid":"Upside down and haloed: the Hanged Man sees anew by letting go.","action":"Describe your situation from the viewpoint of someone who disagrees with you.","related":[{"id":"swords-04-four","reason":"Rest and suspension that prepares for renewal."},{"id":"major-13-death","reason":"Surrender precedes transformation."},{"id":"cups-04-four","reason":"Withdrawal that can either stagnate or reveal new options."}],"numeral":"XII","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-13-death', 'Death', 'major', null, 13, '{"keywords":{"upright":["endings","transformation","transition","release","clearing"],"reversed":["resisting change","stagnation","fear of endings","lingering"]},"traditional":"Waite lists end, mortality, destruction and corruption for the upright card; reversed, inertia, sleep, lethargy and petrifaction.","symbols":[{"element":"Skeleton in armour on a white horse","meaning":"The inevitable, impartial force of change."},{"element":"Banner with a white rose","meaning":"Purity and the promise of renewal within endings."},{"element":"Figures of king, bishop, maiden and child","meaning":"Change comes to everyone regardless of status."},{"element":"Sun rising between two towers","meaning":"A new day — rebirth after the ending."},{"element":"River with a boat","meaning":"The passage from one state to another."}],"upright":"Something is ending so that something new can begin. Death asks you to accept a transition, release what is complete and make space for transformation.","reversed":"Clinging to what is over keeps you stuck. Notice where fear of an ending is preventing natural change.","contexts":{"love":"A relationship pattern — or a relationship — may be ending or transforming into something different.","career":"A job, role or approach is concluding; transition opens the door to new work.","finances":"Old financial habits need to end; restructuring creates healthier foundations.","family":"Family roles are changing; grieving the old form allows a new one to emerge.","growth":"Let an outdated identity or belief go; transformation follows release."},"shadow":"Fear of loss can lead to holding on long after something has died.","misconceptions":["The Death card almost never means literal physical death in reflective practice; it symbolises transformation and endings.","It is not inherently negative — endings are often relief and renewal."],"example":"Someone asking about a friendship that has felt hollow for years draws Death: the card suggests acknowledging that the old form has ended and allowing it to change.","reflection":["What in my life has already ended that I have not yet released?","What might grow in the space that an ending creates?"],"memoryAid":"A white rose on a black banner, a sun between towers: Death clears the way for dawn.","action":"Let go of one thing — an object, habit or commitment — that belongs to a finished chapter.","related":[{"id":"major-12-the-hanged-man","reason":"Surrender that precedes transformation."},{"id":"major-20-judgement","reason":"Rebirth and awakening after an ending."},{"id":"swords-10-ten","reason":"A painful ending with dawn breaking on the horizon."}],"numeral":"XIII","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-14-temperance', 'Temperance', 'major', null, 14, '{"keywords":{"upright":["balance","moderation","patience","blending","healing"],"reversed":["imbalance","excess","impatience","discord"]},"traditional":"Waite gives economy, moderation, frugality, management and accommodation for the upright card; reversed, disunion, unfortunate combinations and competing interests.","symbols":[{"element":"Water poured between two cups","meaning":"Blending opposites into a balanced whole; alchemy and patience."},{"element":"One foot on land, one in water","meaning":"Balance between material and emotional realms."},{"element":"The angel","meaning":"Healing and guidance — often associated with the archangel Michael."},{"element":"Path to a crowned light","meaning":"The long, steady road toward integration and purpose."},{"element":"Irises","meaning":"Messages and the bridge between worlds."}],"upright":"Patience and moderation bring healing. Temperance invites you to blend different elements wisely, find the middle way and let things develop in their own time.","reversed":"Something is out of balance — excess, impatience or conflicting priorities. Look for what needs to be dialled down or brought back into proportion.","contexts":{"love":"Compromise and patience help two different people find a harmonious rhythm.","career":"Collaboration and balancing competing demands lead to steady progress.","finances":"Moderate, consistent saving and spending create stability.","family":"A calm mediator can blend different personalities and needs.","growth":"Integrate opposing parts of yourself; healing happens gradually."},"shadow":"Moderation can become avoidance of strong feelings or necessary conflict.","misconceptions":["Temperance is not about abstinence; it is about the right mixture.","Patience here is active refinement, not passivity."],"example":"Someone burning out from overwork draws Temperance: the card points to a sustainable rhythm that blends effort and rest.","reflection":["What in my life is out of proportion?","Which two things could I blend rather than choose between?"],"memoryAid":"Water flowing between cups: Temperance finds the perfect mix.","action":"Identify one area of excess and reduce it by a small, sustainable amount this week.","related":[{"id":"major-06-the-lovers","reason":"Another angelic card about bringing opposites together."},{"id":"cups-06-six","reason":"Gentle, nourishing exchange."},{"id":"major-15-the-devil","reason":"The next card shows what happens when moderation is lost."}],"numeral":"XIV","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-15-the-devil', 'The Devil', 'major', null, 15, '{"keywords":{"upright":["attachment","compulsion","materialism","shadow self","restriction"],"reversed":["release","breaking free","reclaiming power","awareness of patterns"]},"traditional":"Waite lists ravage, violence, vehemence, force and fatality for the upright card — ''that which is predestined but is not for this reason evil''; reversed, evil fatality, weakness and blindness.","symbols":[{"element":"The horned figure","meaning":"Instinctive appetites and the shadow side given power over us."},{"element":"Loose chains on the couple","meaning":"Bondage that is partly self-chosen — the chains could be lifted off."},{"element":"The inverted pentagram","meaning":"Material concerns placed above spirit."},{"element":"The lowered torch","meaning":"Energy directed downward into compulsion."},{"element":"Echo of the Lovers","meaning":"The same couple, now bound rather than blessed."}],"upright":"Something holds more power over you than it should — a habit, fear, relationship or desire. The Devil asks you to see the chain clearly and recognise that it may be looser than it looks.","reversed":"Awareness is growing and release is possible. You may be ready to break a pattern or reclaim choice — though old habits may pull back.","contexts":{"love":"Look at patterns of dependency, jealousy or control; passion is healthiest when freely chosen.","career":"Feeling trapped by money, status or a toxic environment; consider what you are trading for security.","finances":"Debt, overspending or compulsive habits deserve honest attention.","family":"Unhealthy dynamics or obligations may feel binding; awareness is the first step to change.","growth":"Face your shadow without shame — understanding a compulsion begins to loosen it."},"shadow":"Denial — insisting there is no chain at all — keeps the pattern in place.","misconceptions":["The Devil does not indicate literal evil or supernatural forces; it symbolises attachment and compulsion.","It does not mean you are a bad person; it points to patterns that limit freedom."],"example":"Someone asking why they cannot stop checking their phone at night draws The Devil: the card reflects a compulsive habit and invites them to notice how loose the chain really is.","reflection":["What has more power over me than I want it to?","What do I gain from this attachment, and what does it cost?"],"memoryAid":"Chains loose around their necks: the Devil binds only those who stay.","action":"Name one compulsive habit and create one small barrier to it today.","related":[{"id":"major-06-the-lovers","reason":"Its compositional mirror: free choice versus bondage."},{"id":"swords-08-eight","reason":"Feeling trapped by restrictions that are partly mental."},{"id":"major-16-the-tower","reason":"What happens when false structures are finally broken."}],"numeral":"XV","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-16-the-tower', 'The Tower', 'major', null, 16, '{"keywords":{"upright":["sudden change","upheaval","revelation","collapse of illusions","awakening"],"reversed":["averted disaster","fear of change","delayed upheaval","inner transformation"]},"traditional":"Waite lists misery, distress, adversity, calamity, deception and ruin — unforeseen catastrophe — for the upright card; reversed, the same in a lesser degree, as well as oppression and imprisonment.","symbols":[{"element":"Lightning striking the tower","meaning":"Sudden truth or revelation that shatters false structures."},{"element":"The crown blown off","meaning":"Ego, pride or false authority overthrown."},{"element":"Falling figures","meaning":"Being thrown out of old certainties without warning."},{"element":"Falling flame-drops","meaning":"Divine sparks — insight within the destruction."},{"element":"The rocky crag","meaning":"Foundations that were never as secure as they seemed."}],"upright":"Something built on unstable foundations is coming down. The Tower can be shocking, but it clears away illusions so that you can rebuild on truth.","reversed":"Upheaval may be internal, delayed or narrowly avoided. Resisting a necessary collapse can prolong the discomfort.","contexts":{"love":"A revelation may shake the relationship; honesty, though painful, creates a more truthful foundation.","career":"Sudden change — restructuring, a project collapsing — forces a rethink of direction.","finances":"Unexpected expenses or losses highlight weak financial foundations; build an emergency buffer.","family":"A disruptive event or truth surfaces; stability can be rebuilt on more honest ground.","growth":"A breakthrough in awareness tears down a belief that no longer holds."},"shadow":"Clinging to the ruins and refusing to see what the collapse revealed.","misconceptions":["The Tower does not predict disasters; it symbolises the collapse of false structures and illusions.","It is not purely negative — liberation often follows the shock."],"example":"Someone whose long-term plan suddenly falls through draws The Tower: the card reflects the shock and invites them to notice what the collapse revealed about the plan''s foundations.","reflection":["What structure in my life rests on a shaky foundation?","What truth has recently broken through?"],"memoryAid":"Lightning strikes the crown: the Tower falls so truth can stand.","action":"Identify one assumption that recent events have challenged and write down what you now know instead.","related":[{"id":"major-17-the-star","reason":"Hope and healing following the upheaval."},{"id":"major-13-death","reason":"Transformation through endings, slower and more natural."},{"id":"swords-03-three","reason":"Painful truth that clears the way for healing."}],"numeral":"XVI","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-17-the-star', 'The Star', 'major', null, 17, '{"keywords":{"upright":["hope","renewal","inspiration","healing","serenity"],"reversed":["discouragement","lack of faith","disconnection","despondency"]},"traditional":"Waite records loss, theft and abandonment for the upright card while noting another reading of hope and bright prospects; reversed, arrogance, haughtiness and impotence. Modern practice almost universally follows the ''hope'' reading.","symbols":[{"element":"The great eight-pointed star","meaning":"Guidance, inspiration and hope after darkness."},{"element":"Seven smaller stars","meaning":"The classical planets or chakras: harmony across levels."},{"element":"Water poured on land and pool","meaning":"Renewal of both emotional and material life; generosity flowing freely."},{"element":"The unadorned figure","meaning":"Vulnerability and authenticity — nothing left to hide."},{"element":"The ibis in the tree","meaning":"Thought, wisdom and the soul''s renewal."}],"upright":"After difficulty, hope returns. The Star invites gentle healing, renewed faith in the future and openness to inspiration.","reversed":"Hope feels distant or faith has faded. Small acts of self-care and reconnection with what inspires you can relight the star.","contexts":{"love":"Healing and renewed openness are possible; vulnerability and honesty restore connection.","career":"Inspiration returns; pursue work that feels meaningful and aligned with your hopes.","finances":"Recovery after a setback is possible through steady, hopeful steps.","family":"A period of calm and healing after tension; gentle generosity helps.","growth":"Reconnect with purpose and trust that renewal is underway."},"shadow":"Hope without action can become passive wishing.","misconceptions":["The Star does not guarantee wishes will come true; it represents hope and renewal.","Waite listed loss among its meanings, but the hopeful reading has become standard; both are recorded here for transparency."],"example":"Someone recovering from a long illness draws The Star: the card reflects gradual renewal and encourages gentle optimism.","reflection":["What gives me hope right now?","How can I pour something back into the world from what I have received?"],"memoryAid":"Water poured beneath a great star: hope flows back after the storm.","action":"Write down one hope for the coming month and one small step that nourishes it.","related":[{"id":"major-16-the-tower","reason":"The upheaval the Star heals from."},{"id":"major-18-the-moon","reason":"The next stage: navigating uncertainty by moonlight."},{"id":"cups-01-ace","reason":"Overflowing emotional renewal."}],"numeral":"XVII","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-18-the-moon', 'The Moon', 'major', null, 18, '{"keywords":{"upright":["uncertainty","illusion","intuition","dreams","the unconscious"],"reversed":["clarity emerging","releasing fear","confusion lifting","repressed feelings"]},"traditional":"Waite lists hidden enemies, danger, darkness, deception and error for the upright card; reversed, instability, inconstancy and lesser degrees of deception.","symbols":[{"element":"The moon with a face","meaning":"Reflected, changing light: things are not fully visible."},{"element":"Dog and wolf","meaning":"The tamed and wild sides of our nature responding to the moon."},{"element":"Crayfish emerging from the pool","meaning":"Deep fears and unconscious material rising to the surface."},{"element":"Path between two towers","meaning":"The uncertain road into the unknown between familiar boundaries."},{"element":"Falling drops","meaning":"Influence and nourishment descending, even in darkness."}],"upright":"Not everything is clear, and fear or imagination may distort what you see. The Moon asks you to move carefully, trust intuition and avoid jumping to conclusions.","reversed":"Confusion is beginning to lift, or suppressed fears are surfacing to be faced. Clarity returns as you name what was hidden.","contexts":{"love":"Uncertainty or projections may cloud the relationship; avoid assumptions and seek honest clarity.","career":"Information may be incomplete; verify facts before acting and trust your instincts about what is off.","finances":"Be cautious with unclear deals or unknown terms; read carefully.","family":"Unspoken fears or misunderstandings may be at play; gentle questions help.","growth":"Explore dreams, fears and the unconscious; not every fear reflects reality."},"shadow":"Anxiety can become self-deception, building stories that feel true but are not.","misconceptions":["The Moon does not prove someone is deceiving you; it points to uncertainty and the need for clarity.","It is not purely negative — it is also the card of intuition and imagination."],"example":"Someone anxious about a vague message from their manager draws The Moon: the card suggests asking for clarification instead of imagining the worst.","reflection":["What am I assuming without evidence?","What is my intuition telling me beneath the fear?"],"memoryAid":"Dog and wolf howl at the moon: the path is real, but the shadows deceive.","action":"Write down one fear about your situation, then list what you actually know for certain.","related":[{"id":"major-02-the-high-priestess","reason":"Intuition and hidden knowledge, but calmer and clearer."},{"id":"major-19-the-sun","reason":"The clarity and joy that follow the night."},{"id":"cups-07-seven","reason":"Illusions and fantasies that cloud judgement."}],"numeral":"XVIII","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-19-the-sun', 'The Sun', 'major', null, 19, '{"keywords":{"upright":["joy","vitality","success","clarity","warmth"],"reversed":["temporary setbacks","dimmed enthusiasm","overconfidence","inner child blocked"]},"traditional":"Waite gives material happiness, fortunate marriage and contentment for the upright card; reversed, the same in a lesser sense.","symbols":[{"element":"The radiant sun","meaning":"Life-giving energy, clarity and consciousness."},{"element":"The child on a white horse","meaning":"Innocence, joy and freedom — the renewed self."},{"element":"Sunflowers","meaning":"Growth turning toward the light; abundance."},{"element":"The garden wall","meaning":"Safety and the cultivated life left behind for open joy."},{"element":"The banner","meaning":"Celebration and the victory of vitality."}],"upright":"Clarity, warmth and joy shine on the situation. The Sun invites you to celebrate, express yourself openly and enjoy what is going well.","reversed":"Joy may be dimmed temporarily, or optimism has tipped into overconfidence. The light is still there; let yourself feel it.","contexts":{"love":"Warmth, openness and shared happiness characterise the relationship.","career":"Success, recognition and confidence; your work is seen clearly.","finances":"A positive, stable period; enjoy it while keeping sensible habits.","family":"Joyful time together, play and celebration strengthen bonds.","growth":"Reconnect with playfulness and authentic self-expression."},"shadow":"Relentless positivity can avoid acknowledging real problems.","misconceptions":["Reversed Sun is rarely read as negative; it usually indicates a softer or delayed form of joy.","The card does not guarantee success in a specific venture; it reflects clarity and vitality."],"example":"Someone wondering whether to share their art online draws The Sun: the card encourages confident, joyful self-expression.","reflection":["What is going well that I could celebrate more fully?","When did I last feel playful?"],"memoryAid":"A child on a white horse under a smiling sun: pure, open joy.","action":"Do one thing today simply because it brings you joy, and share it with someone.","related":[{"id":"major-18-the-moon","reason":"The night of uncertainty before the Sun''s clarity."},{"id":"cups-10-ten","reason":"Emotional fulfilment and family happiness."},{"id":"wands-04-four","reason":"Celebration and homecoming."}],"numeral":"XIX","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-20-judgement', 'Judgement', 'major', null, 20, '{"keywords":{"upright":["awakening","reckoning","renewal","calling","absolution"],"reversed":["self-doubt","harsh self-judgement","ignoring a calling","stagnation"]},"traditional":"Waite lists change of position, renewal and outcome for the upright card; reversed, weakness, cowardice and simplicity, as well as deliberation, decision and sentence.","symbols":[{"element":"The angel with a trumpet","meaning":"A call to awaken and rise to a higher purpose."},{"element":"Figures rising from coffins","meaning":"Rebirth and liberation from the past."},{"element":"The red-cross banner","meaning":"Balance and the meeting of spiritual and material."},{"element":"Mountains and water","meaning":"The vast perspective available once one rises."}],"upright":"A call is sounding — to reflect on your path, forgive the past and rise into a new chapter. Judgement asks you to answer it honestly.","reversed":"Self-criticism or fear may stop you from responding to a calling. Release harsh judgement so you can move forward.","contexts":{"love":"Reflect honestly on relationship patterns; forgiveness or a renewed commitment may be needed.","career":"A calling or significant reassessment; consider whether your work reflects who you are becoming.","finances":"Review past decisions, learn from them and make a fresh plan.","family":"Reconciliation and honest reckoning can renew family bonds.","growth":"Wake up to your purpose; let go of past versions of yourself."},"shadow":"Reckoning can become relentless self-judgement that prevents renewal.","misconceptions":["Judgement is not about being judged by others; it is about self-reflection and awakening.","It does not predict a specific external verdict."],"example":"Someone considering returning to study after years away draws Judgement: the card reflects a calling that invites them to rise to a new chapter.","reflection":["What is calling me forward right now?","What past mistake am I ready to forgive?"],"memoryAid":"A trumpet sounds and the sleepers rise: Judgement calls you to awaken.","action":"Write a short letter forgiving yourself for one past decision, and name what you choose now.","related":[{"id":"major-13-death","reason":"Endings that make room for rebirth."},{"id":"major-11-justice","reason":"Accountability on a personal rather than universal scale."},{"id":"major-21-the-world","reason":"The completion that follows awakening."}],"numeral":"XX","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('major-21-the-world', 'The World', 'major', null, 21, '{"keywords":{"upright":["completion","wholeness","achievement","integration","fulfilment"],"reversed":["incompletion","lack of closure","delays","seeking shortcuts"]},"traditional":"Waite gives assured success, recompense, voyage, change of place and emigration for the upright card; reversed, inertia, fixity, stagnation and permanence.","symbols":[{"element":"The dancing figure","meaning":"Freedom and joy in harmony with the whole."},{"element":"The laurel wreath","meaning":"Victory, completion and the cycle closed."},{"element":"Infinity ribbons","meaning":"Continuity: every ending opens a new cycle."},{"element":"Four creatures in the corners","meaning":"The four elements and fixed signs integrated in balance."},{"element":"Two wands","meaning":"Mastery of opposites, held lightly."}],"upright":"A cycle reaches completion and integration. The World invites you to recognise what you have achieved, celebrate it and prepare for the next journey.","reversed":"Something remains unfinished, or closure is missing. Look at the loose ends that need tying up before you move on.","contexts":{"love":"A relationship reaches a fulfilling milestone, or you feel whole within yourself.","career":"Completion of a major project or goal; recognition and readiness for a new challenge.","finances":"A financial goal is reached; secure it and plan the next stage.","family":"A family chapter closes harmoniously; celebrate shared milestones.","growth":"You have integrated important lessons; feel the wholeness before beginning again."},"shadow":"Fear of finishing — staying in the familiar cycle to avoid the unknown next one.","misconceptions":["The World is not a permanent end point; completion leads naturally back to the Fool.","It does not always mean literal world travel, though Waite included voyage among its meanings."],"example":"Someone finishing a degree draws The World: the card reflects completion and encourages celebrating before starting the next chapter.","reflection":["What have I completed that I haven''t fully acknowledged?","What loose ends need closure before I move on?"],"memoryAid":"A dancer in a laurel wreath: the World completes the circle.","action":"Mark a recent completion with a small ritual or celebration, and note one lesson it taught you.","related":[{"id":"major-00-the-fool","reason":"The beginning that follows completion."},{"id":"major-10-wheel-of-fortune","reason":"Shares the four creatures; cycles and wholeness."},{"id":"cups-10-ten","reason":"Emotional fulfilment and harmony."}],"numeral":"XXI","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('wands-01-ace', 'Ace of Wands', 'minor', 'wands', 1, '{"keywords":{"upright":["inspiration","new venture","creative spark","potential","enthusiasm"],"reversed":["delays","lack of motivation","false start","creative block"]},"traditional":"Waite gives creation, invention, enterprise, principle, beginning and source for the upright card; reversed, fall, decadence, ruin and clouded joy.","symbols":[{"element":"Hand from a cloud","meaning":"A gift of energy or opportunity offered from beyond yourself."},{"element":"Sprouting wand","meaning":"Living, growing potential — the idea is alive and ready to develop."},{"element":"Falling leaves","meaning":"Overflowing vitality, more than enough energy to begin."},{"element":"Distant castle","meaning":"The future achievement this spark could grow into."}],"upright":"A spark of inspiration or a new opportunity is offered. Take hold of it while the energy is fresh and give it a first concrete shape.","reversed":"Energy is present but not yet directed, or a venture is starting slowly. Clarify what you actually want to create before forcing momentum.","contexts":{"love":"New passion or renewed excitement; enjoy the spark while letting it develop naturally.","career":"A fresh project, idea or opportunity — grasp it and take a first step.","finances":"A new income idea is promising but still only potential; test it before investing heavily.","family":"Fresh energy in the household — a shared project or new beginning lifts spirits.","growth":"Follow the thing that excites you right now; it may be the start of something significant."},"shadow":"Chasing every new spark so that nothing is developed beyond the first rush.","misconceptions":["Aces show potential, not guaranteed outcomes; the opportunity still has to be taken up."],"example":"Someone asking whether to start a podcast they keep thinking about draws the Ace of Wands: the card encourages recording a first trial episode this week.","reflection":["What idea keeps returning with energy?","What would a first, small expression of it look like?"],"memoryAid":"A hand offers a living branch: the Ace of Wands is a spark waiting to be grasped.","action":"Spend twenty minutes giving your newest idea its first tangible form — a sketch, outline or message.","related":[{"id":"major-01-the-magician","reason":"Shares the raised wand and the power to begin."},{"id":"cups-01-ace","reason":"The same gift of a beginning, in the emotional realm."},{"id":"wands-02-two","reason":"The next stage: planning where to take the spark."}],"numeral":"Ace","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('wands-02-two', 'Two of Wands', 'minor', 'wands', 2, '{"keywords":{"upright":["planning","future vision","decisions","personal power","discovery"],"reversed":["fear of the unknown","playing it safe","poor planning","restlessness"]},"traditional":"Waite describes a lord who has achieved much yet gazes out with some sadness, giving both riches and magnificence and also physical suffering and chagrin; reversed, surprise, wonder, enchantment and fear.","symbols":[{"element":"Globe in hand","meaning":"The world of possibilities held under consideration."},{"element":"One wand held, one fixed","meaning":"What is secure versus what is still to be pursued."},{"element":"Castle battlement","meaning":"A secure base from which to look outward."},{"element":"Rose and lily emblem","meaning":"Passion and purity combined in the plan."}],"upright":"You stand at a vantage point with a secure base and wider horizons. Plan your next move deliberately and decide whether to stay comfortable or venture out.","reversed":"Fear of the unknown or vague planning keeps you on the battlement. A clearer plan can make the next step feel less risky.","contexts":{"love":"Consider what you want long-term; a relationship may be weighing comfort against growth.","career":"Strategic planning, expansion or considering a move abroad or into new territory.","finances":"Map out long-term goals before committing; weigh security against opportunity.","family":"Discuss future plans together — a move, education or a shared ambition.","growth":"Look beyond your current walls; decide what the next horizon is."},"shadow":"Endless planning as a way to avoid actually leaving the castle.","misconceptions":["The Two of Wands is not the journey itself; it is the moment of planning and decision before departure."],"example":"Someone deciding whether to expand a small business to a second city draws the Two of Wands: the card highlights careful planning from their current secure position.","reflection":["What lies beyond my current comfort zone?","What do I need to plan before I can step out?"],"memoryAid":"Globe in hand on the battlements: the Two of Wands plans the world beyond the walls.","action":"Write down where you want to be in a year and three steps to get there.","related":[{"id":"wands-03-three","reason":"The plan set in motion, watching ships go out."},{"id":"major-04-the-emperor","reason":"Authority over one''s domain, and the ambition to extend it."},{"id":"swords-02-two","reason":"Another two facing a decision, but blocked rather than surveying."}],"numeral":"Two","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('wands-03-three', 'Three of Wands', 'minor', 'wands', 3, '{"keywords":{"upright":["expansion","foresight","progress","waiting for results","opportunity abroad"],"reversed":["delays","obstacles","lack of foresight","frustration"]},"traditional":"Waite gives established strength, enterprise, effort, trade and commerce — ships bearing merchandise and able co-operation in business; reversed, the end of troubles and cessation of adversity, toil and disappointment.","symbols":[{"element":"Figure seen from behind","meaning":"Looking ahead; the plans are now in motion."},{"element":"Ships at sea","meaning":"Ventures launched and returns on their way."},{"element":"Three planted wands","meaning":"A stable foundation of effort already in place."},{"element":"High cliff","meaning":"Broad perspective and foresight."}],"upright":"Your efforts are underway and expansion is possible. Keep your eyes on the horizon and prepare for opportunities as results come in.","reversed":"Delays or obstacles frustrate progress. Review your plans and stay patient while adjusting course.","contexts":{"love":"A relationship grows beyond its early stage; long-distance connections or shared plans for the future.","career":"Projects expanding, international opportunities or collaborations bearing fruit.","finances":"Investments of effort begin to return; widen your view of potential income.","family":"Plans for travel or growth; family members venturing out into the world.","growth":"Your horizons are widening; keep learning as new possibilities appear."},"shadow":"Always watching the horizon for the next ship, never enjoying what has arrived.","misconceptions":["The card is about foresight and expansion, not idle waiting — the groundwork has already been done."],"example":"Someone who has applied for several jobs abroad draws the Three of Wands: the card reflects expansion underway and encourages preparing for responses.","reflection":["What have I already set in motion?","How can I prepare for the opportunities on the horizon?"],"memoryAid":"Ships on the horizon, wands planted firm: the Three of Wands watches ventures sail.","action":"Follow up on one thing you have already set in motion.","related":[{"id":"wands-02-two","reason":"The planning stage before ventures are launched."},{"id":"swords-06-six","reason":"Another journey by water, toward calmer shores."},{"id":"major-07-the-chariot","reason":"Forward momentum and ambition."}],"numeral":"Three","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('wands-04-four', 'Four of Wands', 'minor', 'wands', 4, '{"keywords":{"upright":["celebration","homecoming","harmony","milestone","community"],"reversed":["instability at home","cancelled celebration","transition","lack of support"]},"traditional":"Waite gives country life, haven of refuge, a domestic harvest-home, repose, concord, harmony, prosperity and peace; reversed, the meaning remains unaltered — prosperity, increase and felicity.","symbols":[{"element":"Garlanded canopy of four wands","meaning":"A stable structure crowned with celebration — like a wedding canopy."},{"element":"Raised bouquets","meaning":"Joy shared openly with others."},{"element":"Castle behind","meaning":"Security, home and belonging."},{"element":"Gathered crowd","meaning":"Community recognition of a milestone."}],"upright":"A milestone is reached and deserves celebration. Enjoy the stability and togetherness that your efforts have created.","reversed":"Celebrations may be muted or the sense of home unsettled. Focus on rebuilding support and finding joy in smaller gatherings.","contexts":{"love":"Commitment, engagement or moving in together; joyful milestones in a relationship.","career":"Completing a phase of a project; a team celebration or a welcoming new workplace.","finances":"Stability allows you to enjoy what you have built; budget for celebration.","family":"Reunions, homecomings and family events bring warmth.","growth":"Acknowledge how far you have come before pushing on."},"shadow":"Celebrating the image of stability while ignoring tensions underneath.","misconceptions":["Waite noted that this card''s meaning barely changes when reversed — a reversal usually softens rather than overturns it."],"example":"Someone asking how to mark a year of sobriety draws the Four of Wands: the card encourages gathering supportive people to celebrate.","reflection":["What milestone deserves recognition?","Who helps me feel at home?"],"memoryAid":"Four wands and a garland: celebrate the homecoming.","action":"Plan a small celebration — even a meal with one person — to mark something you have achieved.","related":[{"id":"cups-03-three","reason":"Celebration with friends and community."},{"id":"cups-10-ten","reason":"Domestic harmony and family joy."},{"id":"major-19-the-sun","reason":"Open, uncomplicated happiness."}],"numeral":"Four","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('wands-05-five', 'Five of Wands', 'minor', 'wands', 5, '{"keywords":{"upright":["competition","conflict","rivalry","diverse opinions","struggle"],"reversed":["avoiding conflict","resolution","inner conflict","respecting differences"]},"traditional":"Waite describes imitation, as in mock warfare and sham fights — strenuous competition, the battle of life — and also gold and gain; reversed, litigation, disputes, trickery and contradiction.","symbols":[{"element":"Five figures with wands","meaning":"Many people, many agendas, all asserting themselves."},{"element":"Wands crossed chaotically","meaning":"Energy that clashes rather than combines."},{"element":"Varied clothing","meaning":"Different backgrounds and perspectives."},{"element":"No one hurt","meaning":"The struggle is more sport or friction than real danger."}],"upright":"Competing ideas and egos create friction. Use the energy constructively — clarify roles, listen and channel competition into growth.","reversed":"Conflict may be winding down, being avoided or turning inward. Address it honestly rather than letting it simmer.","contexts":{"love":"Bickering or competing needs; turn arguments into honest conversations about what each person wants.","career":"Competitive environment or brainstorming clashes; agree on shared goals.","finances":"Competition for resources; clarify priorities before disagreements escalate.","family":"Squabbles and differing opinions; a structure for discussion helps.","growth":"Healthy competition can sharpen your skills if you don''t take it personally."},"shadow":"Fighting for the sake of being right rather than finding a solution.","misconceptions":["This card rarely describes serious danger; it is friction and competition, often playful."],"example":"Someone frustrated by a chaotic team project draws the Five of Wands: the card suggests organising a meeting to align everyone''s ideas.","reflection":["Is this conflict productive or just noise?","What shared goal could unite the different voices?"],"memoryAid":"Five youths swing wands, nobody falls: friction, not war.","action":"In one disagreement this week, restate the other person''s view before giving yours.","related":[{"id":"swords-05-five","reason":"Conflict with a sharper edge and real losers."},{"id":"wands-07-seven","reason":"Standing your ground against opposition."},{"id":"major-07-the-chariot","reason":"Unifying opposing forces through will."}],"numeral":"Five","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('wands-06-six', 'Six of Wands', 'minor', 'wands', 6, '{"keywords":{"upright":["victory","recognition","success","public acclaim","confidence"],"reversed":["lack of recognition","ego","fall from grace","self-doubt"]},"traditional":"Waite gives a victor triumphing, great news and expectation crowned with its own desire; reversed, apprehension, fear of an enemy at the gate, treachery and indefinite delay.","symbols":[{"element":"Laurel-crowned rider","meaning":"Victory and public acknowledgement."},{"element":"Wreathed wand","meaning":"Success held high for others to see."},{"element":"White horse","meaning":"Strength and purity in the triumph."},{"element":"Crowd with wands","meaning":"Supporters who share in — or helped create — the success."}],"upright":"Your efforts are recognised. Accept the acknowledgement graciously and let it build your confidence.","reversed":"Recognition is delayed, or success has inflated the ego. Find validation in your own standards rather than applause.","contexts":{"love":"Feeling proud of your relationship or being celebrated by a partner; enjoy mutual admiration.","career":"Promotion, praise or a successful launch; your work is seen.","finances":"Rewards for effort; a bonus or gain from recognition.","family":"Pride in a family member''s achievement; celebrate each other.","growth":"Acknowledge your wins and let them build self-belief."},"shadow":"Needing constant applause to feel worthy.","misconceptions":["The card does not guarantee a specific promotion; it reflects recognition and momentum."],"example":"Someone nervous before presenting their thesis draws the Six of Wands: the card reflects confidence and the likelihood of their work being appreciated.","reflection":["What success have I not allowed myself to enjoy?","Who supported me along the way?"],"memoryAid":"Laurels on head and wand: the Six of Wands rides in triumph.","action":"Share a recent win with someone and thank one person who helped.","related":[{"id":"major-07-the-chariot","reason":"Victory through determination."},{"id":"wands-05-five","reason":"The competition before the victory."},{"id":"major-19-the-sun","reason":"Confidence and visible success."}],"numeral":"Six","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('wands-07-seven', 'Seven of Wands', 'minor', 'wands', 7, '{"keywords":{"upright":["standing your ground","perseverance","defence","conviction","challenge"],"reversed":["giving up","overwhelmed","defensiveness","exhaustion"]},"traditional":"Waite gives valour, discussion, wordy strife, negotiations, competition and success; reversed, perplexity, embarrassment and anxiety — a caution against indecision.","symbols":[{"element":"Figure on high ground","meaning":"An advantage of position worth defending."},{"element":"Six wands rising from below","meaning":"Multiple challenges or critics at once."},{"element":"Mismatched shoes","meaning":"Caught unprepared, yet still determined."},{"element":"Single defensive wand","meaning":"Conviction as the main weapon."}],"upright":"You are being challenged, but you hold the higher ground. Stand by your convictions and defend what matters to you.","reversed":"Exhaustion or overwhelm may tempt you to give up, or you may be defending something out of habit. Decide what is worth the fight.","contexts":{"love":"Defending your relationship or your needs within it; hold boundaries without becoming combative.","career":"Competition or criticism; stand by your work with confidence.","finances":"Protect your resources from pressure to overspend or lend.","family":"Standing up for your choices against family opinions.","growth":"Holding to your values even when they are unpopular."},"shadow":"Seeing every disagreement as an attack to be repelled.","misconceptions":["The figure is not losing — the high ground indicates an advantage."],"example":"Someone whose creative proposal is being criticised by colleagues draws the Seven of Wands: the card encourages defending the idea with clear reasons.","reflection":["What am I defending, and is it worth it?","Where do I hold the higher ground?"],"memoryAid":"One wand against six from the hilltop: hold your ground.","action":"Write down the core reasons behind one position you hold, so you can state them calmly.","related":[{"id":"wands-09-nine","reason":"Persistence after many battles."},{"id":"wands-05-five","reason":"Competition and friction among equals."},{"id":"major-08-strength","reason":"Inner courage under pressure."}],"numeral":"Seven","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('wands-08-eight', 'Eight of Wands', 'minor', 'wands', 8, '{"keywords":{"upright":["speed","momentum","rapid progress","messages","movement"],"reversed":["delays","frustration","rushing","scattered energy"]},"traditional":"Waite gives activity in undertakings, swiftness, great haste and great hope, speed toward an end that promises felicity — the arrows of love; reversed, arrows of jealousy, internal dispute and quarrels.","symbols":[{"element":"Eight wands in flight","meaning":"Things in rapid motion; events accelerating."},{"element":"No figures","meaning":"Events moving beyond any one person''s direct control."},{"element":"Parallel direction","meaning":"Alignment — everything heading toward the same target."},{"element":"Open landscape","meaning":"Clear path ahead with few obstacles."}],"upright":"Events move quickly and momentum is on your side. Act promptly, respond to messages and ride the wave of progress.","reversed":"Delays or rushed decisions cause frustration. Slow down enough to aim, or be patient with things not yet in motion.","contexts":{"love":"Quick developments, messages or a whirlwind connection; communicate clearly as things move fast.","career":"Rapid progress, travel or many messages; prioritise and respond efficiently.","finances":"Quick movement of money — in or out; track it carefully.","family":"News arrives quickly; plans come together fast.","growth":"Momentum is building; keep going while energy is high."},"shadow":"Speed that outruns thought, leading to careless choices.","misconceptions":["The card does not literally mean receiving eight messages; it symbolises speed and alignment."],"example":"Someone waiting to hear about a rental application draws the Eight of Wands: the card suggests things may move quickly, so have documents ready.","reflection":["Where is momentum building?","Am I aiming or just moving fast?"],"memoryAid":"Eight wands fly like arrows: swift and straight.","action":"Respond today to the message or task you have been delaying.","related":[{"id":"wands-03-three","reason":"Ventures already launched and now accelerating."},{"id":"swords-12-knight","reason":"Speed and urgency — sometimes too much."},{"id":"major-07-the-chariot","reason":"Directed forward motion."}],"numeral":"Eight","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('wands-09-nine', 'Nine of Wands', 'minor', 'wands', 9, '{"keywords":{"upright":["resilience","persistence","last stand","boundaries","courage"],"reversed":["exhaustion","paranoia","giving up","rigid defensiveness"]},"traditional":"Waite gives strength in opposition — if attacked, the figure will meet the onslaught boldly — as well as delay and adjournment; reversed, obstacles, adversity and calamity.","symbols":[{"element":"Bandaged head","meaning":"Past battles have left their mark."},{"element":"Leaning on a wand","meaning":"Tired but still standing; persistence."},{"element":"Eight wands as a palisade","meaning":"Boundaries built from experience."},{"element":"Wary glance","meaning":"Vigilance — perhaps too much."}],"upright":"You are nearly there, though tired. Draw on your resilience, maintain healthy boundaries and keep going.","reversed":"Exhaustion or suspicion is wearing you down. Consider whether your defences still protect you or have become a cage.","contexts":{"love":"Past hurts may make you guarded; protect yourself while staying open to trust.","career":"Persistence through a final push; don''t give up close to the finish.","finances":"Holding steady through a difficult stretch; protect your reserves.","family":"Weary from ongoing challenges; ask for help while holding boundaries.","growth":"Your resilience has been tested and proven; honour it, then rest."},"shadow":"Treating everyone as a potential threat because of past wounds.","misconceptions":["The Nine of Wands is not defeat; it is endurance near the end of a struggle."],"example":"Someone in the final months of a demanding apprenticeship draws the Nine of Wands: the card encourages persistence while guarding their energy.","reflection":["What has my resilience already carried me through?","Which of my defences are no longer needed?"],"memoryAid":"Bandaged but standing: the Nine of Wands holds the line.","action":"Identify one boundary that protects your energy and one support you can ask for.","related":[{"id":"wands-07-seven","reason":"Defending a position with conviction."},{"id":"wands-10-ten","reason":"The next stage: carrying the full burden."},{"id":"major-08-strength","reason":"Inner resilience and courage."}],"numeral":"Nine","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('wands-10-ten', 'Ten of Wands', 'minor', 'wands', 10, '{"keywords":{"upright":["burden","responsibility","overload","hard work","completion with strain"],"reversed":["delegating","releasing burdens","burnout","collapse"]},"traditional":"Waite gives oppression, but also fortune, gain and success — the oppression of these things; reversed, contrarieties, difficulties and intrigues.","symbols":[{"element":"Ten wands carried in a bundle","meaning":"Taking on every responsibility at once."},{"element":"Bent posture","meaning":"Strain that has become heavy."},{"element":"Face hidden by the wands","meaning":"So burdened you can no longer see where you''re going."},{"element":"Town in the distance","meaning":"The goal is close; the load can soon be set down."}],"upright":"You carry too much. The goal is near, but consider which burdens you could share, delegate or release.","reversed":"You may be ready to put some weight down, or you are close to burnout. Let go before the load drops of its own accord.","contexts":{"love":"One partner carrying too much responsibility; rebalance the load.","career":"Overwork and over-commitment; delegate and prioritise.","finances":"Financial responsibilities feel heavy; review commitments and seek help.","family":"Caretaking burdens; ask other family members to share.","growth":"Notice where you take on more than is yours to carry."},"shadow":"Pride in being the one who carries everything.","misconceptions":["This card is not failure — it is success that has become burdensome."],"example":"Someone running a home, a job and a volunteer role draws the Ten of Wands: the card points to delegating or dropping one commitment.","reflection":["Which of these burdens are truly mine?","What would happen if I put one down?"],"memoryAid":"Ten wands in one pair of arms: too much to carry alone.","action":"List your current commitments and choose one to delegate, postpone or decline.","related":[{"id":"wands-09-nine","reason":"Endurance before the load becomes overwhelming."},{"id":"major-04-the-emperor","reason":"Responsibility and authority — and their weight."},{"id":"pentacles-04-four","reason":"Holding on too tightly."}],"numeral":"Ten","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('wands-11-page', 'Page of Wands', 'minor', 'wands', 11, '{"keywords":{"upright":["enthusiasm","exploration","curiosity","new ideas","messages"],"reversed":["impatience","lack of direction","restlessness","setbacks"]},"traditional":"Waite describes a faithful young person, a lover, an envoy or postman — a bearer of strange tidings; reversed, announcements, evil news and indecision.","symbols":[{"element":"Studying a tall wand","meaning":"Curiosity about a new idea or path."},{"element":"Salamander-patterned tunic","meaning":"Fire energy and the capacity for renewal."},{"element":"Desert and pyramids","meaning":"Exploration of unfamiliar territory and ancient knowledge."},{"element":"Feathered cap","meaning":"Lightness, adventure and freedom."}],"upright":"Approach a new idea with a learner''s enthusiasm. As a role, the Page of Wands is the curious explorer who brings exciting news or possibilities.","reversed":"Enthusiasm may lack direction or patience. Ground your excitement in a simple first plan.","contexts":{"love":"Playful flirtation or fresh excitement; enjoy curiosity without rushing commitment.","career":"A new idea, internship or creative exploration; be willing to learn.","finances":"Explore new income ideas, but research before committing money.","family":"A young or young-at-heart person brings energy and new interests.","growth":"Try something new for the joy of discovery."},"shadow":"Starting many adventures and finishing none.","misconceptions":["Court cards need not represent a specific person; the Page can describe your own beginner''s energy."],"example":"Someone curious about learning to dance draws the Page of Wands: the card encourages signing up for a trial class.","reflection":["What am I curious about right now?","How can I explore it without pressure?"],"memoryAid":"A youth admiring a sprouting wand: the Page of Wands is curious fire.","action":"Spend thirty minutes exploring a topic that excites you, with no goal beyond curiosity.","related":[{"id":"wands-01-ace","reason":"The raw spark the Page begins to explore."},{"id":"major-00-the-fool","reason":"Shared spirit of adventure and new beginnings."},{"id":"wands-12-knight","reason":"The next stage of fiery energy: action and pursuit."}],"numeral":"Page","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('wands-12-knight', 'Knight of Wands', 'minor', 'wands', 12, '{"keywords":{"upright":["action","adventure","boldness","passion","impulsiveness"],"reversed":["recklessness","haste","frustration","scattered energy"]},"traditional":"Waite gives departure, absence, flight, emigration and change of residence; reversed, rupture, division, interruption and discord.","symbols":[{"element":"Rearing horse","meaning":"Energy barely contained — eager to charge."},{"element":"Raised wand","meaning":"Passion and purpose held high."},{"element":"Salamander tunic","meaning":"Fire energy and transformation."},{"element":"Desert and pyramids","meaning":"Adventure in unfamiliar lands."}],"upright":"Bold, energetic action propels you forward. As a role, the Knight of Wands charges toward adventure with confidence and charisma.","reversed":"Haste or impulsiveness leads to burnout or unfinished ventures. Aim before charging.","contexts":{"love":"Passionate, exciting energy — wonderful, but check for consistency.","career":"Taking bold action, travel or a dramatic change; channel enthusiasm into follow-through.","finances":"Impulsive decisions are risky; enthusiasm needs a plan.","family":"A sudden move or adventurous change in the household.","growth":"Embrace courage and adventure while learning patience."},"shadow":"Leaving before things get difficult; restlessness disguised as adventure.","misconceptions":["The Knight does not always mean literal travel, though Waite associated it with departure and change of residence."],"example":"Someone eager to quit a job to travel for a year draws the Knight of Wands: the card reflects bold energy and asks them to plan the practical side.","reflection":["Where do I need to act boldly?","Where might I be charging ahead too fast?"],"memoryAid":"A rearing horse and a raised wand: the Knight of Wands charges into adventure.","action":"Take one bold step toward a goal today — then plan the second step.","related":[{"id":"wands-08-eight","reason":"Speed and momentum."},{"id":"swords-12-knight","reason":"Another knight in full charge, driven by ideas."},{"id":"major-07-the-chariot","reason":"Directed, forceful forward movement."}],"numeral":"Knight","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('wands-13-queen', 'Queen of Wands', 'minor', 'wands', 13, '{"keywords":{"upright":["confidence","warmth","determination","charisma","independence"],"reversed":["jealousy","insecurity","demanding","burnout"]},"traditional":"Waite describes a friendly, loving, honourable person of the countryside, with love of money and success in business; reversed, good, economical and obliging, but also opposition, jealousy and deceit.","symbols":[{"element":"Sunflower in hand","meaning":"Joy, vitality and confident warmth."},{"element":"Black cat at her feet","meaning":"Independence, intuition and comfort with her shadow side."},{"element":"Lion-carved throne","meaning":"Courage and strength held with dignity."},{"element":"Wand held upright","meaning":"Creative authority and self-assurance."}],"upright":"Lead with warmth, confidence and creative energy. As a role, the Queen of Wands is vibrant, determined and generous with her enthusiasm.","reversed":"Confidence may waver or turn demanding and jealous. Reconnect with your own fire rather than measuring yourself against others.","contexts":{"love":"Confident, warm attraction; be yourself fully and let your energy draw others.","career":"Charismatic leadership; take initiative and inspire others.","finances":"Confidence in managing money and growing a business.","family":"A warm, energetic presence holding the household together.","growth":"Own your strengths; shine without apology."},"shadow":"Needing to be the centre of attention; jealousy when others shine.","misconceptions":["The Queen is not limited to women; she describes a mature, confident expression of fire energy."],"example":"Someone hesitating to lead a community event draws the Queen of Wands: the card encourages stepping forward with confidence.","reflection":["Where can I let my confidence shine?","Do I celebrate others'' success as warmly as my own?"],"memoryAid":"Sunflower and black cat: the Queen of Wands is warmth with independence.","action":"Take the lead on one small thing today and do it with visible enthusiasm.","related":[{"id":"major-08-strength","reason":"Courage and the lion as an ally."},{"id":"major-03-the-empress","reason":"Abundant, vibrant creativity."},{"id":"wands-14-king","reason":"Fire energy expressed through vision and leadership."}],"numeral":"Queen","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('wands-14-king', 'King of Wands', 'minor', 'wands', 14, '{"keywords":{"upright":["vision","leadership","entrepreneurship","boldness","inspiration"],"reversed":["impulsiveness","arrogance","unrealistic expectations","domineering"]},"traditional":"Waite describes an honest, conscientious, friendly person, often married, and also news and unexpected inheritance; reversed, good but severe, austere yet tolerant.","symbols":[{"element":"Flowering wand","meaning":"Vision that is alive and continues to grow."},{"element":"Lions and salamanders on the throne","meaning":"Courage and the fire of continual renewal."},{"element":"Living salamander","meaning":"Transformation and the ability to thrive in the heat of challenge."},{"element":"Forward-leaning posture","meaning":"Ready to act on his vision."}],"upright":"Lead with vision and courage. As a role, the King of Wands inspires others, takes calculated risks and turns ideas into lasting ventures.","reversed":"Vision may tip into arrogance or impatience with others. Lead by inspiring, not dominating.","contexts":{"love":"A passionate, committed partner who leads; balance initiative with listening.","career":"Entrepreneurial leadership; set a bold vision and rally people around it.","finances":"Calculated risks and long-term vision in business.","family":"A leader who inspires family goals; avoid imposing your will.","growth":"Step into your role as the author of your own vision."},"shadow":"Expecting everyone to follow your vision without question.","misconceptions":["The King need not be a boss or a man; he describes mature, visionary fire energy."],"example":"Someone considering launching their own studio draws the King of Wands: the card reflects visionary leadership and calculated risk.","reflection":["What vision am I willing to lead?","How do I inspire rather than control?"],"memoryAid":"A king with a flowering wand: vision that grows into a kingdom.","action":"Write a one-paragraph vision statement for a project you care about.","related":[{"id":"major-04-the-emperor","reason":"Authority and leadership."},{"id":"wands-13-queen","reason":"Fire energy expressed with warmth and charisma."},{"id":"wands-02-two","reason":"Planning and surveying a wider domain."}],"numeral":"King","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('cups-01-ace', 'Ace of Cups', 'minor', 'cups', 1, '{"keywords":{"upright":["new feelings","emotional renewal","love","compassion","intuition"],"reversed":["emotional blockage","emptiness","repressed feelings","self-neglect"]},"traditional":"Waite gives the house of the true heart — joy, content, nourishment, abundance and fertility; reversed, the house of the false heart, mutation, instability and revolution.","symbols":[{"element":"Overflowing chalice","meaning":"Emotion and love in abundance, more than can be contained."},{"element":"Five streams","meaning":"The senses filled; love flowing into every part of life."},{"element":"Descending dove with wafer","meaning":"Spiritual grace and peace entering the heart."},{"element":"Water lilies","meaning":"Emotional and spiritual growth rising from deep water."}],"upright":"An opening of the heart: new love, compassion, creativity or emotional healing is offered. Let yourself receive it.","reversed":"Feelings may be blocked or poured out without replenishment. Attend to your own emotional needs first.","contexts":{"love":"New love, renewed affection or a deepening of feeling; be open to receiving.","career":"Work that touches the heart; creative or caring roles bring fulfilment.","finances":"Generosity flows; ensure giving doesn''t outpace replenishment.","family":"Emotional reconnection, new arrivals or renewed tenderness.","growth":"Self-compassion and emotional openness begin something important."},"shadow":"Pouring endlessly for others while the cup inside runs dry.","misconceptions":["The Ace of Cups is not exclusively romantic; it is any new emotional beginning, including self-love."],"example":"Someone asking about reconnecting with an estranged friend draws the Ace of Cups: the card reflects an opportunity for heartfelt renewal.","reflection":["Where is my heart opening right now?","How do I let myself receive care?"],"memoryAid":"A cup that overflows: the Ace of Cups is love beginning to pour.","action":"Express one honest, warm feeling to someone today.","related":[{"id":"major-17-the-star","reason":"Water poured freely in renewal."},{"id":"cups-02-two","reason":"Love shared between two people."},{"id":"wands-01-ace","reason":"The same gift of beginning, in the realm of action."}],"numeral":"Ace","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('cups-02-two', 'Two of Cups', 'minor', 'cups', 2, '{"keywords":{"upright":["partnership","mutual attraction","unity","connection","reciprocity"],"reversed":["imbalance","broken communication","tension","disconnection"]},"traditional":"Waite gives love, passion, friendship, affinity, union, concord and sympathy; reversed, he notes desire turned toward jealousy or imbalance.","symbols":[{"element":"Two figures exchanging cups","meaning":"Mutual offering and acceptance — reciprocity."},{"element":"Caduceus","meaning":"Healing and negotiation between two parties."},{"element":"Winged lion''s head","meaning":"Passion and spiritual blessing over the union."},{"element":"House on a hill","meaning":"A shared home or future together."}],"upright":"A balanced, mutual connection is forming or deepening. Meet the other person as an equal and honour what flows both ways.","reversed":"Balance is off or communication has faltered. Address the imbalance honestly and with care.","contexts":{"love":"Mutual attraction and partnership; a relationship built on equality.","career":"A strong partnership or collaboration with shared values.","finances":"Joint ventures or shared resources based on trust.","family":"Reconciliation or closeness between two family members.","growth":"Integrating two sides of yourself; learning through relationship."},"shadow":"Merging so completely that individuality disappears.","misconceptions":["The card shows mutual connection; it cannot tell you what a specific person privately feels."],"example":"Someone asking about a new business partnership draws the Two of Cups: the card highlights mutual respect and shared values as the foundation.","reflection":["Is this connection mutual?","What am I offering, and what am I receiving?"],"memoryAid":"Two cups, one caduceus: the Two of Cups is a meeting of equals.","action":"Have one conversation this week about what each person needs from a relationship that matters to you.","related":[{"id":"major-06-the-lovers","reason":"Union and values-based choice."},{"id":"cups-01-ace","reason":"The emotional beginning that leads to partnership."},{"id":"cups-10-ten","reason":"Partnership grown into lasting harmony."}],"numeral":"Two","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('cups-03-three', 'Three of Cups', 'minor', 'cups', 3, '{"keywords":{"upright":["friendship","celebration","community","joy","collaboration"],"reversed":["overindulgence","gossip","isolation","third-party tension"]},"traditional":"Waite gives abundance, plenty, merriment, happiness, fulfilment, solace and healing; reversed, expedition, achievement and end, but also excess in physical enjoyment.","symbols":[{"element":"Three women dancing","meaning":"Friendship, community and shared joy."},{"element":"Raised cups","meaning":"Toasting together; celebration."},{"element":"Harvest fruit","meaning":"Abundance worth celebrating."},{"element":"Circle formation","meaning":"Equality and mutual support."}],"upright":"Celebrate with the people who support you. Friendship, community and shared joy nourish everyone.","reversed":"Celebration may become excess, or social dynamics turn sour. Notice whether gatherings leave you nourished or drained.","contexts":{"love":"Social joy and celebration; friends play a role in the relationship''s happiness.","career":"Team success and collaboration; celebrate milestones together.","finances":"Shared abundance; spend on connection, mindful of excess.","family":"Reunions, parties and joyful gatherings.","growth":"Lean on your community; joy shared multiplies."},"shadow":"Using socialising to avoid deeper feelings.","misconceptions":["Reversed does not automatically mean infidelity; it more commonly points to excess or social friction."],"example":"Someone feeling isolated after moving draws the Three of Cups: the card encourages joining a group or reaching out to friends.","reflection":["Who celebrates with me?","How do I contribute to my community?"],"memoryAid":"Three friends, three raised cups: joy shared in a circle.","action":"Arrange a gathering, call or message with friends to celebrate something.","related":[{"id":"wands-04-four","reason":"Celebration and homecoming."},{"id":"pentacles-03-three","reason":"Collaboration and teamwork."},{"id":"cups-10-ten","reason":"Wider emotional fulfilment."}],"numeral":"Three","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('cups-04-four', 'Four of Cups', 'minor', 'cups', 4, '{"keywords":{"upright":["apathy","contemplation","withdrawal","missed opportunity","re-evaluation"],"reversed":["renewed interest","acceptance","moving on","seizing opportunity"]},"traditional":"Waite gives weariness, disgust, aversion and imaginary vexations, with the offered cup representing a new possibility; reversed, novelty, presage, new instruction and new relations.","symbols":[{"element":"Arms crossed","meaning":"Closed off, protecting oneself from feeling."},{"element":"Three cups on the grass","meaning":"What has been offered before and now feels stale."},{"element":"Hand offering a fourth cup","meaning":"A new opportunity that is not yet noticed."},{"element":"Tree","meaning":"Retreat into contemplation."}],"upright":"Dissatisfaction leads you inward. Reflection is healthy, but make sure you don''t miss what is being offered now.","reversed":"You may be emerging from apathy, ready to engage again — or you may be withdrawing further. Notice which.","contexts":{"love":"Feeling uninspired; look again at what your partner or life is offering.","career":"Boredom or disengagement; a new opportunity may be overlooked.","finances":"Taking resources for granted; review what you already have.","family":"Withdrawal from family; check in with what is going unspoken.","growth":"Contemplation leads to clarity, if it doesn''t harden into apathy."},"shadow":"Waiting for something perfect while rejecting what is good.","misconceptions":["The card is not simply laziness; it often describes genuine reflection or emotional fatigue."],"example":"Someone bored in their routine draws the Four of Cups: the card suggests noticing a new offer they''ve dismissed too quickly.","reflection":["What am I taking for granted?","What opportunity might I be overlooking?"],"memoryAid":"Arms crossed beneath the tree: the Four of Cups misses the offered cup.","action":"List three things currently being offered to you — help, invitations, chances — and reconsider one.","related":[{"id":"major-12-the-hanged-man","reason":"A pause that can bring a new perspective."},{"id":"cups-07-seven","reason":"Choices and offerings that require discernment."},{"id":"major-09-the-hermit","reason":"Withdrawal for introspection."}],"numeral":"Four","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('cups-05-five', 'Five of Cups', 'minor', 'cups', 5, '{"keywords":{"upright":["loss","grief","regret","disappointment","focus on the negative"],"reversed":["acceptance","moving on","forgiveness","healing"]},"traditional":"Waite gives loss, but something remains over — an inheritance that does not correspond to expectations; reversed, news, alliances, return and false projects.","symbols":[{"element":"Dark cloak","meaning":"Mourning and grief."},{"element":"Three spilled cups","meaning":"What has been lost."},{"element":"Two upright cups behind","meaning":"What remains, not yet noticed."},{"element":"Bridge to a castle","meaning":"A path forward toward home and healing."}],"upright":"Grief and disappointment are real and deserve acknowledgement. When you are ready, turn around: something valuable remains.","reversed":"Healing and acceptance are beginning. You may be ready to cross the bridge toward what still remains.","contexts":{"love":"Grief over a loss or disappointment; healing begins with acknowledgement.","career":"A setback or loss; examine what can still be salvaged.","finances":"Financial loss or regret; focus on what remains and rebuild.","family":"Grief or estrangement; recognise the bonds that still exist.","growth":"Allow grief, then gently notice what endures."},"shadow":"Staying focused on loss so long that remaining blessings go unseen.","misconceptions":["The card does not say everything is lost — two cups still stand."],"example":"Someone grieving a failed project draws the Five of Cups: the card validates the loss and points to skills and relationships that remain.","reflection":["What have I lost, and what still stands?","What would help me cross the bridge?"],"memoryAid":"Three spilled, two standing: the Five of Cups mourns but is not empty.","action":"Write down one loss and, beside it, two things that remain.","related":[{"id":"swords-03-three","reason":"Heartbreak and emotional pain."},{"id":"cups-06-six","reason":"Looking back with tenderness rather than grief."},{"id":"pentacles-05-five","reason":"Hardship with help close by but unseen."}],"numeral":"Five","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('cups-06-six', 'Six of Cups', 'minor', 'cups', 6, '{"keywords":{"upright":["nostalgia","childhood","innocence","kindness","reunion"],"reversed":["stuck in the past","unrealistic nostalgia","moving forward","leaving home"]},"traditional":"Waite gives looking back on the past, childhood memories and things that have vanished, and also new relations and new knowledge; reversed, the future, renewal and what will soon come to pass.","symbols":[{"element":"Child offering a cup of flowers","meaning":"Simple kindness and innocent generosity."},{"element":"Old village courtyard","meaning":"Familiar places from the past."},{"element":"Six flower-filled cups","meaning":"Memories that still bloom."},{"element":"Guard walking away","meaning":"Safety and protection that allow innocence."}],"upright":"Memories, kindness and simple pleasures bring comfort. Reconnecting with the past — or your inner child — can nourish the present.","reversed":"Nostalgia may be keeping you from the present, or you are ready to move forward from old patterns.","contexts":{"love":"Reunion with an old flame or tender, playful affection; ensure the past isn''t idealised.","career":"Returning to an old interest or using skills learned long ago.","finances":"Gifts, inheritance or generosity; avoid spending to recapture the past.","family":"Childhood memories, family reunions and kindness between generations.","growth":"Reconnect with what delighted you as a child."},"shadow":"Idealising the past to avoid the challenges of now.","misconceptions":["Waite reads the reversed card as pointing toward the future rather than simply ''bad nostalgia''."],"example":"Someone searching for a new hobby draws the Six of Cups: the card suggests revisiting something they loved as a child.","reflection":["What simple joy from my past could I bring into today?","Am I romanticising something that is gone?"],"memoryAid":"A child offers flowers in a cup: the Six of Cups is kindness remembered.","action":"Do something today that you loved as a child.","related":[{"id":"cups-05-five","reason":"Looking back with grief rather than tenderness."},{"id":"major-19-the-sun","reason":"Childlike joy and innocence."},{"id":"pentacles-10-ten","reason":"Family legacy and generations."}],"numeral":"Six","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('cups-07-seven', 'Seven of Cups', 'minor', 'cups', 7, '{"keywords":{"upright":["choices","illusion","wishful thinking","imagination","temptation"],"reversed":["clarity","decisiveness","reality check","alignment"]},"traditional":"Waite gives fairy favours, images of reflection, sentiment and imagination — some attainment, but nothing permanent; reversed, desire, will, determination and project.","symbols":[{"element":"Seven cups on clouds","meaning":"Possibilities that may be dreams rather than realities."},{"element":"Varied visions","meaning":"Wealth, victory, danger, temptation and spiritual illumination all competing."},{"element":"Silhouetted figure","meaning":"The chooser, overwhelmed and seen only in outline."},{"element":"Veiled glowing figure","meaning":"The true self or higher purpose, hidden among distractions."}],"upright":"Many options shimmer, but not all are real. Separate fantasy from feasible choices before committing.","reversed":"Clarity is returning, and you are ready to choose. Commit to the option grounded in reality and values.","contexts":{"love":"Idealising a person or possibility; look at what is real.","career":"Too many options or unrealistic plans; prioritise and research.","finances":"Beware get-rich-quick fantasies; evaluate opportunities soberly.","family":"Unrealistic expectations of family members; clarify what is possible.","growth":"Use imagination to dream, then choose one dream to make real."},"shadow":"Living in daydreams to avoid the effort of choosing.","misconceptions":["The card does not say every option is false; it asks you to test which are real."],"example":"Someone overwhelmed by career options after a course draws the Seven of Cups: the card suggests shortlisting realistic paths and testing one.","reflection":["Which of my options are real, and which are wishes?","What does the veiled figure — my deeper purpose — want?"],"memoryAid":"Seven cups in the clouds: dreams to sift, not all to drink.","action":"Write down your options and mark each as ''tested'', ''researched'' or ''only imagined''.","related":[{"id":"major-18-the-moon","reason":"Illusion and uncertainty."},{"id":"cups-04-four","reason":"Choosing — or refusing — what is offered."},{"id":"swords-02-two","reason":"Indecision and avoidance of a choice."}],"numeral":"Seven","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('cups-08-eight', 'Eight of Cups', 'minor', 'cups', 8, '{"keywords":{"upright":["walking away","seeking deeper meaning","disillusionment","transition","emotional courage"],"reversed":["fear of change","aimless drifting","staying too long","returning"]},"traditional":"Waite gives the decline of a matter, or a successful matter abandoned; also modesty and timidity; reversed, great joy, happiness and feasting.","symbols":[{"element":"Figure walking away","meaning":"Choosing to leave what no longer fulfils."},{"element":"Eight stacked cups with a gap","meaning":"Something is missing despite outward success."},{"element":"Moon and sun together","meaning":"A threshold time; intuition guiding the decision."},{"element":"Rocky mountains","meaning":"A harder, more meaningful path ahead."}],"upright":"You may need to leave something that looks complete but no longer feeds you. Have the courage to seek deeper meaning.","reversed":"Fear of change or uncertainty keeps you from leaving — or you may be drifting without direction. Clarify what you are seeking.","contexts":{"love":"Walking away from a relationship pattern or situation that no longer fulfils you.","career":"Leaving a stable job for more meaningful work; following a calling.","finances":"Letting go of material security for something more aligned.","family":"Stepping back from family expectations to find your own path.","growth":"Leave behind what is comfortable but empty."},"shadow":"Running away from every situation as soon as it gets difficult.","misconceptions":["The card is not abandonment for its own sake; it is a conscious search for deeper meaning."],"example":"Someone in a well-paid but unfulfilling job draws the Eight of Cups: the card reflects the courage to explore more meaningful work.","reflection":["What looks complete but feels empty?","What am I truly seeking?"],"memoryAid":"Eight cups left behind under the moon: walk on toward meaning.","action":"Name one thing you''ve outgrown and one step to explore what''s next.","related":[{"id":"major-09-the-hermit","reason":"Solitary search for meaning."},{"id":"swords-06-six","reason":"Transition toward calmer waters."},{"id":"major-13-death","reason":"Endings that create room for transformation."}],"numeral":"Eight","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('cups-09-nine', 'Nine of Cups', 'minor', 'cups', 9, '{"keywords":{"upright":["contentment","satisfaction","gratitude","wishes fulfilled","emotional security"],"reversed":["smugness","dissatisfaction","materialism","unfulfilled wishes"]},"traditional":"Waite gives concord, contentment, physical well-being, victory and satisfaction; reversed, truth, loyalty and liberty — though he notes readings vary, including mistakes and imperfections.","symbols":[{"element":"Contented figure with crossed arms","meaning":"Satisfaction and pride in what has been gained."},{"element":"Nine cups in an arc","meaning":"Emotional abundance displayed."},{"element":"Draped bench","meaning":"Comfort and what lies behind the display."},{"element":"Red cap","meaning":"Vitality and enjoyment."}],"upright":"Emotional and material satisfaction is within reach. Enjoy it with gratitude.","reversed":"Satisfaction may be superficial or wishes unfulfilled. Look at what would truly content you.","contexts":{"love":"Contentment and emotional satisfaction; appreciate what you share.","career":"Achievement and satisfaction with your work.","finances":"Comfort and security; enjoy without overindulgence.","family":"Harmony and contentment at home.","growth":"Practise gratitude for what you have achieved."},"shadow":"Complacency or showing off rather than sharing.","misconceptions":["Often called the ''wish card'', it reflects satisfaction — not a guarantee of a specific wish."],"example":"Someone reflecting on a year of hard work draws the Nine of Cups: the card invites them to enjoy and appreciate what they''ve built.","reflection":["What am I grateful for right now?","What would genuine contentment look like?"],"memoryAid":"Nine cups in a proud arc: the Nine of Cups is satisfaction.","action":"Write down nine things you are grateful for today.","related":[{"id":"cups-10-ten","reason":"Contentment shared with others."},{"id":"pentacles-09-nine","reason":"Material self-sufficiency and comfort."},{"id":"major-21-the-world","reason":"Fulfilment and completion."}],"numeral":"Nine","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('cups-10-ten', 'Ten of Cups', 'minor', 'cups', 10, '{"keywords":{"upright":["harmony","emotional fulfilment","family","happiness","alignment"],"reversed":["disconnection","broken harmony","misaligned values","family conflict"]},"traditional":"Waite gives contentment and repose of the entire heart, the perfection of human love and friendship; reversed, repose of the false heart, indignation and violence.","symbols":[{"element":"Rainbow of ten cups","meaning":"Emotional fulfilment and blessing after a storm."},{"element":"Couple with raised arms","meaning":"Gratitude and shared joy."},{"element":"Dancing children","meaning":"Innocence and the next generation''s happiness."},{"element":"Cottage by a river","meaning":"Home, stability and flowing emotion."}],"upright":"Lasting emotional harmony and happiness. Appreciate the loving connections in your life.","reversed":"Harmony is strained or values are misaligned. Reconnect through honest communication.","contexts":{"love":"Long-term happiness and emotional commitment.","career":"A harmonious workplace that feels like family; meaningful work-life balance.","finances":"Security that supports a happy home life.","family":"Family harmony and joyful togetherness.","growth":"Align your life with what brings lasting emotional fulfilment."},"shadow":"Keeping up an image of a perfect family while avoiding real issues.","misconceptions":["The card does not require a traditional family; any loving community qualifies."],"example":"Someone asking how to improve home life draws the Ten of Cups: the card points to shared joy and honest connection.","reflection":["What does emotional fulfilment look like for me?","How do I nurture harmony at home?"],"memoryAid":"A rainbow of cups over a dancing family: the Ten of Cups is the heart''s home.","action":"Spend focused, joyful time with the people who matter most to you.","related":[{"id":"pentacles-10-ten","reason":"Material legacy and family stability."},{"id":"major-19-the-sun","reason":"Joy and warmth."},{"id":"wands-04-four","reason":"Celebration at home."}],"numeral":"Ten","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('cups-11-page', 'Page of Cups', 'minor', 'cups', 11, '{"keywords":{"upright":["creative opportunity","curiosity","intuitive messages","sensitivity","playfulness"],"reversed":["emotional immaturity","creative block","escapism","insecurity"]},"traditional":"Waite describes a studious youth impelled to render service, and news, messages, reflection and meditation; reversed, taste, inclination, attachment, deception and artifice.","symbols":[{"element":"Fish peeking from the cup","meaning":"A surprising, imaginative idea emerging from the unconscious."},{"element":"Lotus-patterned tunic","meaning":"Emotional and spiritual openness."},{"element":"Sea behind","meaning":"The depths of feeling and intuition."},{"element":"Relaxed stance","meaning":"Playfulness and receptivity."}],"upright":"Be open to gentle surprises — creative ideas, emotional insights or intuitive messages. As a role, the Page of Cups is sensitive, imaginative and curious.","reversed":"Emotional immaturity or escapism may be at play. Ground your feelings and creativity in something real.","contexts":{"love":"Sweet, playful affection or a new romantic interest; express feelings openly.","career":"Creative opportunities or a new artistic idea; follow your curiosity.","finances":"Imaginative ideas need practical grounding before investment.","family":"A sensitive young person or a tender family message.","growth":"Listen to your intuition and dreams with curiosity."},"shadow":"Escaping into fantasy to avoid emotional responsibility.","misconceptions":["The Page need not be a child; it can represent your own emotional curiosity."],"example":"Someone wondering whether to try writing poetry draws the Page of Cups: the card encourages playful creative exploration.","reflection":["What surprising idea or feeling has surfaced lately?","How can I be playful with my emotions?"],"memoryAid":"A fish peeks from the cup: the Page of Cups delights in surprise.","action":"Create something small and playful today — a doodle, a poem, a song.","related":[{"id":"cups-01-ace","reason":"New emotional beginnings."},{"id":"major-02-the-high-priestess","reason":"Intuitive messages from within."},{"id":"cups-12-knight","reason":"Emotion moving into romantic action."}],"numeral":"Page","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('cups-12-knight', 'Knight of Cups', 'minor', 'cups', 12, '{"keywords":{"upright":["romance","charm","following the heart","idealism","invitations"],"reversed":["moodiness","unrealistic expectations","jealousy","disappointment"]},"traditional":"Waite gives arrival and approach — a messenger bringing advances, propositions and invitations; reversed, trickery, artifice, subtlety and duplicity.","symbols":[{"element":"Cup held forward","meaning":"An offer, invitation or heartfelt gesture."},{"element":"Calm white horse","meaning":"Gentle, measured movement guided by emotion."},{"element":"Winged helmet","meaning":"Imagination and messages carried swiftly."},{"element":"Flowing river","meaning":"Emotional flow and movement."}],"upright":"Follow your heart with grace. As a role, the Knight of Cups is the romantic idealist who brings invitations and heartfelt offers.","reversed":"Idealism may become moodiness or unrealistic expectations. Check that offers — yours or others'' — are sincere.","contexts":{"love":"Romantic gestures, proposals or invitations; enjoy them while staying grounded.","career":"Creative proposals or work aligned with your passions.","finances":"An appealing offer — check the details before accepting.","family":"A peacemaker who brings emotional warmth.","growth":"Follow what moves you, with awareness of reality."},"shadow":"Being in love with love rather than with a real person or situation.","misconceptions":["The Knight of Cups doesn''t guarantee a proposal; it reflects romantic, idealistic energy."],"example":"Someone invited to collaborate on an art project draws the Knight of Cups: the card reflects a heartfelt invitation worth considering.","reflection":["What is my heart inviting me toward?","Am I seeing this situation realistically?"],"memoryAid":"A knight offers a cup at a walking pace: romance arrives gently.","action":"Make one heartfelt gesture toward someone or something you care about.","related":[{"id":"cups-02-two","reason":"Mutual attraction and union."},{"id":"major-06-the-lovers","reason":"Love and choices of the heart."},{"id":"cups-13-queen","reason":"Emotional maturity and depth."}],"numeral":"Knight","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('cups-13-queen', 'Queen of Cups', 'minor', 'cups', 13, '{"keywords":{"upright":["compassion","emotional depth","intuition","nurturing","calm"],"reversed":["emotional overwhelm","codependency","insecurity","self-neglect"]},"traditional":"Waite describes a good, honest and devoted person with loving intelligence and the gift of vision; reversed, he records widely varying readings, from a distinguished but untrustworthy person to vice and dishonour.","symbols":[{"element":"Ornate lidded chalice","meaning":"The depths of the unconscious, guarded and respected."},{"element":"Throne at the water''s edge","meaning":"Living close to emotion without being swept away."},{"element":"Cherubs and shell","meaning":"Love, imagination and the sea''s creative power."},{"element":"Contemplative gaze","meaning":"Deep intuition and emotional attunement."}],"upright":"Lead with compassion and emotional wisdom. As a role, the Queen of Cups is intuitive, nurturing and emotionally steady.","reversed":"You may be absorbing others'' feelings or neglecting your own. Set emotional boundaries and care for yourself.","contexts":{"love":"Deep emotional connection, empathy and nurturing love.","career":"Caring professions or roles where emotional intelligence matters.","finances":"Intuition helps, but balance it with practical checks.","family":"A compassionate presence who supports others emotionally.","growth":"Honour your intuition and emotional depth."},"shadow":"Losing yourself in others'' emotions; martyrdom.","misconceptions":["Sensitivity is strength here, not weakness or passivity."],"example":"Someone supporting a grieving friend draws the Queen of Cups: the card encourages compassionate presence with healthy boundaries.","reflection":["What is my intuition telling me?","How can I care for others without losing myself?"],"memoryAid":"A queen by the sea gazing into her closed cup: feeling deeply, held steadily.","action":"Check in with your own feelings before helping someone else today.","related":[{"id":"major-02-the-high-priestess","reason":"Intuition and the unconscious."},{"id":"cups-14-king","reason":"Emotional mastery and balance."},{"id":"major-03-the-empress","reason":"Nurturing presence."}],"numeral":"Queen","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('cups-14-king', 'King of Cups', 'minor', 'cups', 14, '{"keywords":{"upright":["emotional balance","diplomacy","calm authority","compassion","wisdom"],"reversed":["emotional manipulation","moodiness","repression","volatility"]},"traditional":"Waite describes a responsible person of business, law or divinity, disposed to oblige — equity, art and creative intelligence; reversed, a dishonest, double-dealing person, injustice and considerable loss.","symbols":[{"element":"Throne floating on a choppy sea","meaning":"Calm amid emotional turbulence."},{"element":"Cup and sceptre","meaning":"Emotion held together with authority."},{"element":"Fish amulet","meaning":"Creativity and the unconscious, worn with ease."},{"element":"Ship and leaping fish","meaning":"Navigating feelings and allowing creativity to surface."}],"upright":"Stay calm and compassionate under pressure. As a role, the King of Cups balances heart and head, leading with diplomacy.","reversed":"Emotions may be repressed or used to manipulate. Acknowledge feelings honestly rather than controlling them.","contexts":{"love":"A stable, emotionally mature partner; calm communication.","career":"Diplomatic leadership; managing people with empathy.","finances":"Steady, balanced decisions without emotional impulsiveness.","family":"A calm, supportive presence who mediates conflict.","growth":"Master your emotions without suppressing them."},"shadow":"Appearing calm while suppressing feelings until they erupt.","misconceptions":["Emotional control is not the same as emotional suppression."],"example":"Someone managing a tense team conflict draws the King of Cups: the card suggests calm, empathetic leadership.","reflection":["How can I stay steady without suppressing my feelings?","Where is diplomacy needed?"],"memoryAid":"A king afloat on rough seas, cup steady: calm heart in the storm.","action":"When a strong emotion arises, name it out loud or in writing before deciding what to do.","related":[{"id":"major-14-temperance","reason":"Balance and moderation."},{"id":"cups-13-queen","reason":"Emotional depth and intuition."},{"id":"swords-14-king","reason":"Authority through intellect rather than feeling."}],"numeral":"King","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('swords-01-ace', 'Ace of Swords', 'minor', 'swords', 1, '{"keywords":{"upright":["clarity","breakthrough","truth","mental focus","new idea"],"reversed":["confusion","miscommunication","clouded judgement","harsh words"]},"traditional":"Waite gives triumph, the excessive degree in everything, conquest and the triumph of force; reversed, the same but with disastrous results.","symbols":[{"element":"Upright sword from a cloud","meaning":"A gift of clarity, truth or decisive thought."},{"element":"Golden crown at the tip","meaning":"Victory of the mind and mastery of thought."},{"element":"Olive and palm","meaning":"Peace and victory — the two outcomes clarity can bring."},{"element":"Jagged mountains","meaning":"The challenges that clear thinking must cut through."}],"upright":"A breakthrough of clarity cuts through confusion. Speak the truth, make the decision and think clearly.","reversed":"Thoughts are clouded or words used carelessly. Pause and gather facts before cutting.","contexts":{"love":"Honest communication brings clarity; say what needs to be said with care.","career":"A breakthrough idea or clear decision; communicate decisively.","finances":"Clear-eyed analysis; cut unnecessary expenses.","family":"Truth-telling clears the air; use words kindly.","growth":"Mental clarity and new understanding."},"shadow":"Using truth as a weapon rather than a tool.","misconceptions":["The Ace of Swords is not inherently violent; it is the power of clear thought."],"example":"Someone stuck on a confusing contract draws the Ace of Swords: the card suggests seeking a clear explanation of each clause.","reflection":["What truth needs to be acknowledged?","Where do I need clarity rather than more information?"],"memoryAid":"A crowned sword from the clouds: the Ace of Swords cuts through fog.","action":"Write your situation in one clear sentence, then name the decision it requires.","related":[{"id":"major-11-justice","reason":"Truth and clear judgement."},{"id":"swords-14-king","reason":"Mastery of intellect and authority."},{"id":"wands-01-ace","reason":"The same gift of beginning, in the realm of action."}],"numeral":"Ace","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('swords-02-two', 'Two of Swords', 'minor', 'swords', 2, '{"keywords":{"upright":["indecision","stalemate","avoidance","difficult choice","truce"],"reversed":["information overload","confusion","lesser of two evils","decision made"]},"traditional":"Waite gives conformity, equipoise, courage and friendship — concord in a state of arms; reversed, imposture, falsehood and duplicity.","symbols":[{"element":"Blindfold","meaning":"Refusing to see, or deciding without being swayed by appearances."},{"element":"Crossed swords","meaning":"Two options held in tense balance."},{"element":"Arms across the heart","meaning":"Protecting the heart from the decision''s emotional cost."},{"element":"Sea and rocks behind","meaning":"Emotions and obstacles the figure is not facing."}],"upright":"You may be avoiding a choice to keep the peace. Remove the blindfold, look at the options and decide.","reversed":"Confusion or too much information overwhelms you — or the stalemate is breaking. Choose with the best information available.","contexts":{"love":"Avoiding a difficult conversation; honesty breaks the stalemate.","career":"Torn between options; gather information, then decide.","finances":"Postponing a financial decision; delay may cost more.","family":"Staying neutral to avoid conflict; consider whether silence helps.","growth":"Face what you''ve been avoiding looking at."},"shadow":"Calling avoidance ''balance''.","misconceptions":["The card is not always negative — Waite also reads it as courage and concord."],"example":"Someone choosing between two job offers draws the Two of Swords: the card encourages removing the blindfold by listing what each truly offers.","reflection":["What decision am I avoiding?","What would I see if I removed the blindfold?"],"memoryAid":"Blindfolded with crossed swords: the Two of Swords holds a choice it won''t face.","action":"Set a deadline for one decision you''ve been postponing.","related":[{"id":"cups-07-seven","reason":"Too many options and confusion."},{"id":"major-02-the-high-priestess","reason":"A seated figure before water, guarding knowledge."},{"id":"swords-08-eight","reason":"Blindfolded and feeling trapped."}],"numeral":"Two","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('swords-03-three', 'Three of Swords', 'minor', 'swords', 3, '{"keywords":{"upright":["heartbreak","grief","painful truth","sorrow","release"],"reversed":["recovery","forgiveness","releasing pain","lingering hurt"]},"traditional":"Waite gives removal, absence, delay, division, rupture and dispersion; reversed, mental alienation, error, loss, distraction and confusion.","symbols":[{"element":"Heart pierced by three swords","meaning":"Pain caused by words, thoughts or truths."},{"element":"Storm clouds and rain","meaning":"Grief that needs to be expressed — tears that clear the air."},{"element":"No figures","meaning":"Pain experienced as a universal state."}],"upright":"A painful truth or loss hurts. Allow yourself to grieve; the rain eventually clears.","reversed":"Healing is beginning, or old pain lingers. Forgiveness — of others or yourself — may help release it.","contexts":{"love":"Heartbreak, painful words or disappointment; allow grief and seek support.","career":"Hurtful feedback or loss; separate the facts from the pain.","finances":"Disappointment with a financial outcome; grieve, then plan.","family":"Hurt within the family; honest, compassionate conversation helps healing.","growth":"Pain can bring clarity about what matters."},"shadow":"Replaying painful words long after they were spoken.","misconceptions":["The card reflects pain, not a prediction of betrayal by a specific person."],"example":"Someone hurt by a friend''s criticism draws the Three of Swords: the card validates the pain and encourages processing it before responding.","reflection":["What hurt needs to be acknowledged?","What truth does this pain reveal?"],"memoryAid":"Three swords, one heart, falling rain: grief allowed becomes release.","action":"Write down what hurt and what you need now — then share it with someone safe.","related":[{"id":"cups-05-five","reason":"Grief and loss."},{"id":"major-16-the-tower","reason":"Painful revelation."},{"id":"swords-04-four","reason":"The rest and recovery that follow."}],"numeral":"Three","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('swords-04-four', 'Four of Swords', 'minor', 'swords', 4, '{"keywords":{"upright":["rest","recovery","contemplation","retreat","restoration"],"reversed":["restlessness","burnout","returning to activity","stagnation"]},"traditional":"Waite gives vigilance, retreat, solitude, the hermit''s repose, exile, tomb and coffin; reversed, wise administration, circumspection, economy and precaution.","symbols":[{"element":"Knight effigy at rest","meaning":"Deep rest and suspension of activity."},{"element":"Hands joined in prayer","meaning":"Contemplation and inner peace."},{"element":"Three swords on the wall, one below","meaning":"Conflicts set aside; one thought still held."},{"element":"Stained-glass window","meaning":"Spiritual sanctuary and reflection."}],"upright":"Rest is needed. Step back to recover, reflect and restore your energy before the next challenge.","reversed":"Restlessness or burnout — or readiness to re-engage after recovery. Don''t skip rest you still need.","contexts":{"love":"Taking space to recover from conflict; time apart may restore calm.","career":"Take a break or holiday to avoid burnout.","finances":"Pause major decisions; consolidate.","family":"Quiet time at home restores balance after stress.","growth":"Meditation and rest are part of progress, not a pause from it."},"shadow":"Withdrawing indefinitely to avoid re-engaging with life.","misconceptions":["The tomb imagery does not predict death; it symbolises rest and retreat."],"example":"Someone exhausted after months of caregiving draws the Four of Swords: the card encourages arranging respite.","reflection":["How do I truly rest?","What do I need to recover from?"],"memoryAid":"A knight lies still beneath three swords: rest before the next battle.","action":"Schedule a block of genuine rest — no screens, no tasks — this week.","related":[{"id":"major-09-the-hermit","reason":"Retreat and solitude."},{"id":"major-12-the-hanged-man","reason":"Suspension and pause."},{"id":"swords-03-three","reason":"The pain that rest helps heal."}],"numeral":"Four","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('swords-05-five', 'Five of Swords', 'minor', 'swords', 5, '{"keywords":{"upright":["conflict","hollow victory","tension","winning at a cost","betrayal of values"],"reversed":["reconciliation","making amends","moving on","lingering resentment"]},"traditional":"Waite gives degradation, destruction, revocation, infamy, dishonour and loss; reversed, burial and obsequies.","symbols":[{"element":"Smirking figure gathering swords","meaning":"Winning, but at others'' expense."},{"element":"Two figures walking away","meaning":"Defeat, hurt and broken relationships."},{"element":"Torn, windy sky","meaning":"Tension and unsettled atmosphere after conflict."},{"element":"Swords on the ground","meaning":"Weapons given up — or taken."}],"upright":"A conflict may be won at too high a cost. Consider whether being right is worth the damage.","reversed":"The desire to reconcile is growing, or resentment lingers. Make amends where you can.","contexts":{"love":"Arguments where someone ''wins'' but the relationship loses; seek understanding.","career":"Ruthless competition or office politics; consider your integrity.","finances":"Gains made at others'' expense can backfire.","family":"Family conflict leaving hurt feelings; prioritise relationship over victory.","growth":"Choose your battles wisely."},"shadow":"Needing to win every argument.","misconceptions":["The card doesn''t always place you as the ''bad'' figure — you might be any of the three."],"example":"Someone who ''won'' an argument but feels uneasy draws the Five of Swords: the card invites reflection on the cost of winning.","reflection":["Is this conflict worth what it costs?","Which figure am I in this scene?"],"memoryAid":"One gathers swords while two walk away: the Five of Swords is a hollow win.","action":"Reach out to repair one relationship strained by conflict.","related":[{"id":"wands-05-five","reason":"Competition without real harm."},{"id":"swords-07-seven","reason":"Deception and strategy."},{"id":"major-11-justice","reason":"Fairness and accountability."}],"numeral":"Five","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('swords-06-six', 'Six of Swords', 'minor', 'swords', 6, '{"keywords":{"upright":["transition","moving on","leaving difficulty behind","travel","recovery"],"reversed":["resistance to change","unfinished business","carrying baggage","turbulent transition"]},"traditional":"Waite gives journey by water, route, way, envoy and expedient; reversed, declaration, confession and publicity.","symbols":[{"element":"Ferryman poling a boat","meaning":"Guided transition — sometimes with help."},{"element":"Cloaked woman and child","meaning":"Vulnerability and grief carried through change."},{"element":"Six upright swords in the boat","meaning":"Thoughts and memories taken along on the journey."},{"element":"Rough water behind, calm ahead","meaning":"Leaving turmoil for calmer conditions."}],"upright":"You are moving away from difficulty toward calmer waters. The transition may be sad, but it leads to recovery.","reversed":"Unfinished business or resistance makes the transition harder. Decide what to leave behind.","contexts":{"love":"Moving on from a difficult period or relationship toward peace.","career":"Transitioning to a new role or leaving a stressful environment.","finances":"Gradual recovery from financial strain.","family":"A move or transition that brings relief.","growth":"Healing through gradual change."},"shadow":"Bringing every old worry into the new place.","misconceptions":["The card can mean literal travel by water, but more often a transition from turmoil to calm."],"example":"Someone relocating after a painful breakup draws the Six of Swords: the card reflects a sad but healing transition.","reflection":["What am I leaving behind?","What do I need to bring — and what can I let go of?"],"memoryAid":"A boat glides from rough to calm water: the Six of Swords moves on.","action":"Identify one thought or habit from a difficult period that you can leave behind.","related":[{"id":"cups-08-eight","reason":"Walking away from what no longer serves."},{"id":"wands-03-three","reason":"Ships and journeys outward."},{"id":"major-14-temperance","reason":"Healing and calm."}],"numeral":"Six","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('swords-07-seven', 'Seven of Swords', 'minor', 'swords', 7, '{"keywords":{"upright":["deception","strategy","stealth","getting away with something","going it alone"],"reversed":["confession","conscience","coming clean","self-deception"]},"traditional":"Waite gives design, attempt, wish, hope and confidence, but also quarrelling and a plan that may fail; reversed, good advice, counsel, wisdom and instruction, as well as slander.","symbols":[{"element":"Figure tiptoeing away","meaning":"Acting covertly or avoiding confrontation."},{"element":"Five swords carried, two left","meaning":"Taking what one can, not everything."},{"element":"Backward glance","meaning":"Awareness of risk; checking whether one is seen."},{"element":"Camp of tents","meaning":"The group or community being left or deceived."}],"upright":"Strategy or secrecy is at play — possibly deception, possibly a clever workaround. Check whether your actions align with your values.","reversed":"Conscience is stirring; it may be time to come clean or to stop deceiving yourself.","contexts":{"love":"Be honest with yourself and your partner; secrecy erodes trust. The card cannot reveal another''s private actions.","career":"Strategic thinking or office politics; act with integrity.","finances":"Be careful of scams and double-check agreements.","family":"Avoidance or keeping secrets; consider honest conversation.","growth":"Examine where you might be deceiving yourself."},"shadow":"Justifying dishonesty as cleverness.","misconceptions":["The card does not prove someone is lying to you; it highlights strategy, secrecy and self-deception as themes to examine."],"example":"Someone tempted to skip a step in a work process draws the Seven of Swords: the card asks whether the shortcut compromises integrity.","reflection":["Where am I avoiding being fully honest?","Is my strategy aligned with my values?"],"memoryAid":"Tiptoeing away with five swords: the Seven of Swords tries to get away with it.","action":"Identify one small dishonesty — with yourself or others — and correct it.","related":[{"id":"swords-05-five","reason":"Winning at the expense of integrity."},{"id":"major-18-the-moon","reason":"Deception and hidden things."},{"id":"major-01-the-magician","reason":"Skill used to persuade."}],"numeral":"Seven","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('swords-08-eight', 'Eight of Swords', 'minor', 'swords', 8, '{"keywords":{"upright":["feeling trapped","restriction","self-limiting beliefs","powerlessness","fear"],"reversed":["release","new perspective","freedom","self-acceptance"]},"traditional":"Waite gives bad news, violent chagrin, crisis, censure, power in trammels and conflict; reversed, disquiet, difficulty, opposition, accident and the unforeseen.","symbols":[{"element":"Blindfold and loose bindings","meaning":"Restriction that is partly mental; freedom is closer than it seems."},{"element":"Eight swords around her","meaning":"Thoughts that seem to box one in."},{"element":"Marshy ground","meaning":"Emotional uncertainty underfoot."},{"element":"Distant castle","meaning":"Authority or safety that feels out of reach."}],"upright":"You may feel trapped, but some of the bindings are beliefs. Look for the gaps between the swords.","reversed":"You are beginning to see a way out. Freedom comes from questioning the thoughts that held you.","contexts":{"love":"Feeling stuck; examine fears that limit communication or choices.","career":"Feeling trapped in a job; list options you haven''t considered.","finances":"Constraints may feel absolute; seek advice to find hidden options.","family":"Obligations feel binding; communicate needs.","growth":"Challenge the beliefs that make you feel powerless."},"shadow":"Preferring the familiarity of the trap over the uncertainty of freedom.","misconceptions":["The figure is not truly trapped — the bindings are loose and the path is open."],"example":"Someone convinced they can''t change careers draws the Eight of Swords: the card encourages questioning that belief and exploring small steps.","reflection":["Which of my limits are real, and which are beliefs?","What would I do if I weren''t afraid?"],"memoryAid":"Blindfolded among eight swords, bindings loose: the trap is mostly in the mind.","action":"Write down one ''I can''t'' and rewrite it as ''I haven''t yet found a way to…''.","related":[{"id":"major-15-the-devil","reason":"Bondage that can be escaped."},{"id":"swords-02-two","reason":"Blindfolded and avoiding."},{"id":"swords-09-nine","reason":"Anxiety and mental suffering."}],"numeral":"Eight","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('swords-09-nine', 'Nine of Swords', 'minor', 'swords', 9, '{"keywords":{"upright":["anxiety","worry","sleeplessness","fear","rumination"],"reversed":["hope","reaching out","recovery from anxiety","deep-seated fear"]},"traditional":"Waite gives death, failure, miscarriage, delay, deception, disappointment and despair; reversed, imprisonment, suspicion, doubt, reasonable fear and shame.","symbols":[{"element":"Figure sitting up in bed, face in hands","meaning":"Night-time anxiety and despair."},{"element":"Nine swords on the wall","meaning":"Thoughts lined up, but not touching the figure."},{"element":"Quilt of roses and zodiac signs","meaning":"Comfort and larger perspective available beneath the fear."},{"element":"Dark room","meaning":"Isolation of worry in the night."}],"upright":"Anxiety is loud right now. Remember that the swords are on the wall, not in you — share the worry and test it against reality.","reversed":"Worry may be easing, or it has become deep-seated. Reaching out for support helps.","contexts":{"love":"Worries or insecurities about the relationship; talk them through rather than ruminating.","career":"Work stress keeping you up; break the problem into manageable steps.","finances":"Financial anxiety; facing the numbers often reduces fear.","family":"Worry about a loved one; share the concern.","growth":"Learn tools for managing anxious thoughts."},"shadow":"Treating worst-case thoughts as predictions.","misconceptions":["The card reflects anxiety, not a prophecy of what you fear. If anxiety is persistent, a health professional can help."],"example":"Someone lying awake over an exam draws the Nine of Swords: the card suggests writing down the worry and a plan, then resting.","reflection":["What am I most afraid of, and how likely is it?","Who could I share this worry with?"],"memoryAid":"Nine swords on the wall, not in the heart: night fears are louder than facts.","action":"Write down your biggest worry, the evidence for and against it, and one action you can take.","related":[{"id":"major-18-the-moon","reason":"Fear and uncertainty in the dark."},{"id":"swords-08-eight","reason":"Feeling trapped by thoughts."},{"id":"swords-10-ten","reason":"Reaching rock bottom — and the dawn beyond."}],"numeral":"Nine","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('swords-10-ten', 'Ten of Swords', 'minor', 'swords', 10, '{"keywords":{"upright":["painful ending","rock bottom","betrayal","exhaustion","the worst is over"],"reversed":["recovery","regeneration","resisting an ending","lessons learned"]},"traditional":"Waite says the card signifies whatever is intimated by the design — pain, affliction, tears, sadness and desolation — and notes it is not especially a card of violent death; reversed, advantage, profit and success, though none permanent.","symbols":[{"element":"Figure pierced by ten swords","meaning":"A dramatic, definitive ending — it cannot get worse."},{"element":"Dark sky","meaning":"The depth of the difficulty."},{"element":"Golden dawn on the horizon","meaning":"A new day beginning; recovery is coming."},{"element":"Calm water","meaning":"Peace after the struggle."}],"upright":"Something has reached its painful end. The worst is over — dawn is breaking, and recovery can begin.","reversed":"You are recovering, or resisting an ending that has already happened. Let it be over.","contexts":{"love":"A painful ending; acknowledge it fully so that healing can begin.","career":"A difficult end to a role or project; the next phase will be different.","finances":"A low point that clarifies what must change.","family":"A painful chapter closes; space for renewal opens.","growth":"Rock bottom can become a foundation for rebuilding."},"shadow":"Dramatising pain so that recovery feels impossible.","misconceptions":["The card does not predict physical harm — Waite himself said it is not especially a card of violent death."],"example":"Someone whose business closed draws the Ten of Swords: the card acknowledges the painful end and points to the dawn of a new chapter.","reflection":["What has truly ended?","What does the dawn on the horizon represent for me?"],"memoryAid":"Ten swords, but the sky turns gold: the end of the worst.","action":"Name what has ended and one small action that belongs to the new day.","related":[{"id":"major-13-death","reason":"Endings and transformation."},{"id":"swords-09-nine","reason":"Anxiety before the ending."},{"id":"major-17-the-star","reason":"Hope and healing afterward."}],"numeral":"Ten","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('swords-11-page', 'Page of Swords', 'minor', 'swords', 11, '{"keywords":{"upright":["curiosity","new ideas","vigilance","honest questions","learning"],"reversed":["gossip","all talk","defensiveness","scattered thoughts"]},"traditional":"Waite gives authority, overseeing, secret service, vigilance, spying and examination; reversed, the more evil side of these qualities, the unforeseen and unprepared.","symbols":[{"element":"Sword held upright with both hands","meaning":"Eagerness to engage with ideas and truth."},{"element":"Windswept hill","meaning":"Shifting thoughts and changing perspectives."},{"element":"Scattering birds","meaning":"Ideas and messages in the air."},{"element":"Alert stance","meaning":"Vigilance and readiness."}],"upright":"Approach the situation with curiosity and sharp questions. As a role, the Page of Swords is the eager student and observer.","reversed":"Ideas may scatter or words turn into gossip. Think before speaking.","contexts":{"love":"Honest, curious conversation; avoid over-analysing.","career":"Learning new skills, research and asking good questions.","finances":"Research before making decisions; gather information.","family":"A curious young person, or the need for open dialogue.","growth":"Cultivate curiosity and intellectual honesty."},"shadow":"Using information to gossip or spy rather than understand.","misconceptions":["The Page of Swords is not necessarily a literal spy; Waite''s ''vigilance'' is better read as alert observation."],"example":"Someone starting a new job draws the Page of Swords: the card encourages asking questions and observing carefully.","reflection":["What question do I most need to ask?","Am I listening as much as I speak?"],"memoryAid":"A youth on a windy hill, sword high: the Page of Swords is curious and alert.","action":"Write down three questions about your situation and seek an answer to one.","related":[{"id":"swords-01-ace","reason":"Mental clarity and new ideas."},{"id":"swords-12-knight","reason":"Thought moving rapidly into action."},{"id":"pentacles-11-page","reason":"Another curious student, of practical matters."}],"numeral":"Page","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('swords-12-knight', 'Knight of Swords', 'minor', 'swords', 12, '{"keywords":{"upright":["ambition","decisive action","fast thinking","assertiveness","drive"],"reversed":["recklessness","aggression","impatience","scattered focus"]},"traditional":"Waite gives skill, bravery, capacity, defence and address, and also enmity, wrath and war; reversed, imprudence, incapacity and extravagance.","symbols":[{"element":"Knight charging at full gallop","meaning":"Rapid, decisive action driven by thought."},{"element":"Sword raised forward","meaning":"Determination to cut through obstacles."},{"element":"Wind-bent trees","meaning":"The force — and disruption — of fast movement."},{"element":"Butterflies and birds on the harness","meaning":"Air energy: ideas and intellect."}],"upright":"Charge ahead with clarity and conviction. As a role, the Knight of Swords is quick, ambitious and fearless — sometimes too fast.","reversed":"Speed has become recklessness or aggression. Slow down and consider consequences.","contexts":{"love":"Direct, passionate communication; avoid steamrolling your partner.","career":"Pushing forward decisively; balance speed with care.","finances":"Quick decisions may be risky; double-check.","family":"Strong opinions clash; listen as well as speak.","growth":"Harness drive while learning patience."},"shadow":"Rushing in without listening.","misconceptions":["The Knight of Swords is not purely aggressive; directness and courage are strengths."],"example":"Someone eager to confront a colleague draws the Knight of Swords: the card supports addressing the issue but warns against charging in angrily.","reflection":["Where do I need decisive action?","Where might speed harm me or others?"],"memoryAid":"A knight charges into the wind, sword first: thought at full gallop.","action":"Act decisively on one stalled item — after pausing for one minute to consider its impact.","related":[{"id":"wands-12-knight","reason":"Another knight in full, energetic charge."},{"id":"major-07-the-chariot","reason":"Driven forward motion."},{"id":"swords-14-king","reason":"Intellect matured into wise judgement."}],"numeral":"Knight","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('swords-13-queen', 'Queen of Swords', 'minor', 'swords', 13, '{"keywords":{"upright":["clarity","independence","honest communication","perceptiveness","boundaries"],"reversed":["coldness","bitterness","harsh criticism","isolation"]},"traditional":"Waite gives widowhood, female sadness and embarrassment, absence, mourning, privation and separation; reversed, malice, bigotry, artifice and deceit.","symbols":[{"element":"Sword held upright","meaning":"Truth and clear judgement."},{"element":"Extended hand","meaning":"Openness — welcoming honest exchange."},{"element":"Butterflies on the throne","meaning":"Transformation and the air element."},{"element":"Single bird in the sky","meaning":"Clear perspective and solitude of thought."}],"upright":"Speak clearly and honestly, with boundaries. As a role, the Queen of Swords is perceptive, independent and wise through experience.","reversed":"Clarity may become coldness or harsh criticism. Temper truth with compassion.","contexts":{"love":"Honest communication and healthy boundaries; independence within relationship.","career":"Clear-headed decisions and direct communication.","finances":"Rational, unsentimental financial choices.","family":"A truthful voice that helps cut through emotional confusion.","growth":"Learn from past pain to gain clarity and wisdom."},"shadow":"Using wit or truth to keep others at a distance.","misconceptions":["Modern readings emphasise perceptiveness and independence rather than Waite''s ''widowhood''; the history is recorded for transparency."],"example":"Someone needing to give honest feedback draws the Queen of Swords: the card encourages clarity delivered with fairness.","reflection":["What truth needs to be spoken clearly?","How can I be honest without being harsh?"],"memoryAid":"A queen above the clouds, sword upright, hand open: truth with grace.","action":"Communicate one honest boundary clearly and kindly.","related":[{"id":"major-11-justice","reason":"Impartial clarity."},{"id":"swords-14-king","reason":"Intellectual authority."},{"id":"cups-13-queen","reason":"Wisdom through feeling rather than thought."}],"numeral":"Queen","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('swords-14-king', 'King of Swords', 'minor', 'swords', 14, '{"keywords":{"upright":["intellectual authority","truth","clear judgement","ethics","leadership"],"reversed":["manipulation","abuse of power","cold logic","rigid thinking"]},"traditional":"Waite says whatever arises from the idea of judgement — power, command, authority, militant intelligence and law; reversed, cruelty, perversity and evil intention.","symbols":[{"element":"Upright sword","meaning":"Clear, principled judgement."},{"element":"Butterflies and crescent moons on the throne","meaning":"Transformation guided by intellect."},{"element":"Frontal pose","meaning":"Directness and accountability."},{"element":"Cypress trees and birds","meaning":"Steadfastness and elevated perspective."}],"upright":"Lead with clarity, fairness and principle. As a role, the King of Swords is the wise judge or advisor.","reversed":"Intellect may be used to manipulate or to dismiss feelings. Combine logic with ethics and empathy.","contexts":{"love":"Honest, rational conversations; ensure emotions are also heard.","career":"Strategic leadership, legal or analytical roles; decide with integrity.","finances":"Objective analysis and expert advice.","family":"A fair arbiter in disputes.","growth":"Develop principled thinking and intellectual honesty."},"shadow":"Believing logic alone is enough.","misconceptions":["The King of Swords is not necessarily cold; at his best he is fair and principled."],"example":"Someone facing a complex legal decision draws the King of Swords: the card suggests seeking expert, objective advice.","reflection":["What is the fair and principled choice?","Am I honouring both reason and feeling?"],"memoryAid":"A king facing forward, sword raised: judgement clear and fair.","action":"Make one decision today based on principle rather than convenience.","related":[{"id":"major-11-justice","reason":"Truth and fair judgement."},{"id":"major-04-the-emperor","reason":"Authority and structure."},{"id":"cups-14-king","reason":"Authority through emotional balance."}],"numeral":"King","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('pentacles-01-ace', 'Ace of Pentacles', 'minor', 'pentacles', 1, '{"keywords":{"upright":["opportunity","prosperity","new venture","manifestation","stability"],"reversed":["missed opportunity","poor planning","scarcity mindset","instability"]},"traditional":"Waite gives perfect contentment, felicity, ecstasy and speedy intelligence — gold; reversed, the evil side of wealth and bad intelligence.","symbols":[{"element":"Golden pentacle in a hand from a cloud","meaning":"A tangible opportunity offered — something real to build on."},{"element":"Lily garden","meaning":"Cultivated abundance and purity of intent."},{"element":"Hedge archway","meaning":"A gateway to a new phase of material life."},{"element":"Distant mountains","meaning":"Long-term goals reachable through steady effort."}],"upright":"A concrete opportunity for growth — work, money, health or home — is available. Plant the seed and tend it practically.","reversed":"An opportunity may slip by without a plan, or scarcity thinking blocks you. Ground your intentions in practical steps.","contexts":{"love":"Building something stable together; practical commitment.","career":"A job offer, new venture or tangible opportunity.","finances":"New income or savings opportunity; plan for growth.","family":"A new home or practical improvement for the family.","growth":"Invest in your health and practical well-being."},"shadow":"Valuing security so much that no seed is ever planted.","misconceptions":["The Ace of Pentacles is not instant wealth; it is a seed that needs cultivation."],"example":"Someone offered a small freelance contract draws the Ace of Pentacles: the card suggests accepting it as a seed for future work.","reflection":["What practical opportunity is in front of me?","What would I need to cultivate it?"],"memoryAid":"A golden coin offered over a garden: the Ace of Pentacles is a seed of prosperity.","action":"Take one practical step toward a material goal — open a savings account, send an application, plant something.","related":[{"id":"pentacles-10-ten","reason":"The long-term legacy a seed can grow into."},{"id":"major-03-the-empress","reason":"Abundance and growth."},{"id":"wands-01-ace","reason":"The same gift of beginning, in the realm of action."}],"numeral":"Ace","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('pentacles-02-two', 'Two of Pentacles', 'minor', 'pentacles', 2, '{"keywords":{"upright":["balance","adaptability","juggling priorities","flexibility","time management"],"reversed":["overwhelm","disorganisation","overcommitment","imbalance"]},"traditional":"Waite gives gaiety and recreation, and also news and messages in writing, obstacles, agitation and embroilment; reversed, enforced gaiety and simulated enjoyment.","symbols":[{"element":"Juggling two pentacles","meaning":"Balancing competing priorities."},{"element":"Infinity ribbon","meaning":"The ongoing, endless flow of balancing."},{"element":"Ships on rolling waves","meaning":"Ups and downs of life handled with flexibility."},{"element":"Dancing posture","meaning":"Lightness and adaptability under pressure."}],"upright":"You are juggling priorities. Stay flexible and keep a light touch while finding a sustainable rhythm.","reversed":"Too many balls in the air; something will drop. Simplify and prioritise.","contexts":{"love":"Balancing relationship with other commitments; make time deliberately.","career":"Multitasking and adapting to change; manage time carefully.","finances":"Balancing budgets and expenses; track cash flow.","family":"Juggling family needs; share responsibilities.","growth":"Find a sustainable rhythm amid change."},"shadow":"Pretending to cope while silently overwhelmed.","misconceptions":["The card is not chaos — it shows skilful, if precarious, balance."],"example":"Someone working while studying draws the Two of Pentacles: the card encourages a flexible schedule with clear priorities.","reflection":["What am I juggling right now?","What could I put down?"],"memoryAid":"Two coins in an infinity loop: keep juggling, lightly.","action":"List your current priorities and choose the top two for this week.","related":[{"id":"major-10-wheel-of-fortune","reason":"Change and fluctuation."},{"id":"major-14-temperance","reason":"Balance and moderation."},{"id":"wands-10-ten","reason":"When juggling becomes carrying too much."}],"numeral":"Two","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('pentacles-03-three', 'Three of Pentacles', 'minor', 'pentacles', 3, '{"keywords":{"upright":["teamwork","collaboration","skill","learning","recognition of craft"],"reversed":["lack of teamwork","misalignment","poor quality","disregard for skill"]},"traditional":"Waite gives métier, trade, skilled labour, nobility, renown and glory; reversed, mediocrity in work and otherwise, pettiness and weakness.","symbols":[{"element":"Stonemason in a cathedral","meaning":"Skilled work in service of something larger."},{"element":"Monk and patron with plans","meaning":"Collaboration between different expertise."},{"element":"Three pentacles carved in the arch","meaning":"Work built into a lasting structure."},{"element":"Gothic architecture","meaning":"Craft, tradition and long-term building."}],"upright":"Collaborate and bring your skills to a shared project. Good work is recognised when people combine expertise.","reversed":"Teamwork falters or quality slips. Clarify roles and standards.","contexts":{"love":"Building a relationship together; each partner contributes.","career":"Collaboration, apprenticeship and recognition of skill.","finances":"Working with experts or partners on financial plans.","family":"Working together on a shared home project.","growth":"Learn from others and contribute your expertise."},"shadow":"Insisting on doing everything your own way.","misconceptions":["The card values collaboration as much as individual skill."],"example":"Someone renovating a kitchen draws the Three of Pentacles: the card suggests consulting skilled professionals and collaborating on the plan.","reflection":["Who could I collaborate with?","How is my skill contributing to something larger?"],"memoryAid":"A mason, a monk and a patron at the arch: the Three of Pentacles builds together.","action":"Ask for input from someone with different expertise on your current project.","related":[{"id":"pentacles-08-eight","reason":"Skill developed through practice."},{"id":"major-05-the-hierophant","reason":"Learning within a tradition."},{"id":"cups-03-three","reason":"Celebration and community."}],"numeral":"Three","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('pentacles-04-four', 'Four of Pentacles', 'minor', 'pentacles', 4, '{"keywords":{"upright":["security","saving","control","possessiveness","conservation"],"reversed":["greed","letting go","financial insecurity","generosity"]},"traditional":"Waite gives the surety of possessions, cleaving to what one has, gift, legacy and inheritance; reversed, suspense, delay and opposition.","symbols":[{"element":"Pentacle clutched to the chest","meaning":"Holding tightly to resources or emotions."},{"element":"Pentacles under the feet","meaning":"Grounded in material security — but unable to move."},{"element":"Pentacle on the crown","meaning":"Thoughts dominated by material concerns."},{"element":"City behind","meaning":"Separation from community to protect possessions."}],"upright":"Security matters, but holding too tightly limits growth. Save wisely, and notice where control becomes fear.","reversed":"You may be releasing control — or anxiety about money is increasing. Seek balance between saving and living.","contexts":{"love":"Possessiveness or fear of loss; trust and openness are needed.","career":"Protecting your position; consider whether caution limits growth.","finances":"Saving and security; avoid hoarding out of fear.","family":"Holding onto family traditions or resources too tightly.","growth":"Let go of control to allow new experiences."},"shadow":"Believing security can be guaranteed by holding on tighter.","misconceptions":["Saving and stability are healthy; the card warns only against fear-driven control."],"example":"Someone hesitant to spend any money on a course that could advance their career draws the Four of Pentacles: the card asks whether caution has become fear.","reflection":["What am I holding onto out of fear?","What would healthy security look like?"],"memoryAid":"Coins on head, heart and feet: the Four of Pentacles holds too tight.","action":"Make one generous or growth-oriented use of your resources this week.","related":[{"id":"wands-10-ten","reason":"Burdened by holding too much."},{"id":"pentacles-06-six","reason":"The flow of giving and receiving."},{"id":"major-04-the-emperor","reason":"Control and structure."}],"numeral":"Four","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('pentacles-05-five', 'Five of Pentacles', 'minor', 'pentacles', 5, '{"keywords":{"upright":["hardship","financial loss","isolation","worry","exclusion"],"reversed":["recovery","help received","end of hardship","spiritual poverty"]},"traditional":"Waite gives material trouble above all, destitution — though he also records an alternative reading of love, lovers and affinities; reversed, disorder, chaos, ruin and discord.","symbols":[{"element":"Two figures in the snow","meaning":"Hardship and feeling left out in the cold."},{"element":"Crutches and bandaged leg","meaning":"Physical or practical struggle."},{"element":"Lit stained-glass window","meaning":"Help and sanctuary nearby, unnoticed."},{"element":"Falling snow","meaning":"A difficult season."}],"upright":"Hardship or exclusion is weighing on you. Help may be closer than it seems — look for the lit window.","reversed":"Recovery is beginning, help is arriving, or you are ready to accept support.","contexts":{"love":"Feeling left out or unsupported; reach out and ask for what you need.","career":"Job loss or insecurity; seek support and resources.","finances":"Financial hardship; seek advice and assistance.","family":"Feeling excluded or struggling together; lean on community.","growth":"Notice where you deny yourself help."},"shadow":"Pride or shame preventing you from asking for help.","misconceptions":["The card does not predict poverty; it reflects hardship and the availability of help."],"example":"Someone struggling after a job loss draws the Five of Pentacles: the card encourages seeking support services and community.","reflection":["Where is the lit window I haven''t noticed?","What help am I refusing?"],"memoryAid":"Two in the snow past a glowing window: help is near.","action":"Ask for one specific form of help today.","related":[{"id":"cups-05-five","reason":"Loss and focus on what is missing."},{"id":"pentacles-06-six","reason":"Help and generosity received."},{"id":"major-09-the-hermit","reason":"Isolation, chosen or not."}],"numeral":"Five","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('pentacles-06-six', 'Six of Pentacles', 'minor', 'pentacles', 6, '{"keywords":{"upright":["generosity","charity","giving and receiving","sharing","fairness"],"reversed":["strings attached","debt","power imbalance","one-sided giving"]},"traditional":"Waite gives presents, gifts and gratification, attention and vigilance — present prosperity; reversed, desire, cupidity, envy and jealousy.","symbols":[{"element":"Merchant with balanced scales","meaning":"Fair, measured generosity."},{"element":"Coins given to kneeling figures","meaning":"The flow of resources from those who have to those who need."},{"element":"Six pentacles","meaning":"Abundance shared."},{"element":"Two recipients","meaning":"Our position may shift between giving and receiving."}],"upright":"Resources flow between people. Give generously and receive gracefully; fairness keeps the exchange healthy.","reversed":"Giving may come with strings, or the balance of power is off. Examine debts and dynamics.","contexts":{"love":"Generosity and balance in the relationship.","career":"Mentorship, fair pay or receiving support.","finances":"Loans, gifts or charity; ensure fairness.","family":"Sharing resources within the family fairly.","growth":"Practise both generosity and receiving."},"shadow":"Using generosity to gain control or gratitude.","misconceptions":["The card is about the flow of resources — you may be the giver or the receiver."],"example":"Someone asked to lend money to a relative draws the Six of Pentacles: the card points to clear, fair terms.","reflection":["Am I giving and receiving in balance?","Are there strings attached?"],"memoryAid":"Scales in one hand, coins in the other: the Six of Pentacles gives fairly.","action":"Give something — time, money or skill — with no strings attached.","related":[{"id":"pentacles-05-five","reason":"Need and hardship."},{"id":"major-11-justice","reason":"Fairness and balance."},{"id":"pentacles-04-four","reason":"Holding versus sharing."}],"numeral":"Six","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('pentacles-07-seven', 'Seven of Pentacles', 'minor', 'pentacles', 7, '{"keywords":{"upright":["patience","long-term investment","assessment","perseverance","growth"],"reversed":["impatience","poor returns","lack of reward","wasted effort"]},"traditional":"Waite gives money, business and barter, and also altercation, quarrels, innocence and purgation; reversed, anxiety about money one may lend, impatience, apprehension and suspicion.","symbols":[{"element":"Farmer leaning on a hoe","meaning":"Pausing to assess progress."},{"element":"Pentacles growing on a vine","meaning":"Investment that grows slowly."},{"element":"Thoughtful gaze","meaning":"Evaluating whether effort is paying off."},{"element":"Open field","meaning":"Patient cultivation over time."}],"upright":"Your efforts are growing, slowly. Pause to assess and decide whether to keep investing.","reversed":"Impatience or disappointing returns; reconsider where you invest your energy.","contexts":{"love":"A relationship that needs patient tending; assess honestly.","career":"Long-term projects; evaluate progress and adjust.","finances":"Investments take time; review before changing strategy.","family":"Patient nurturing of family relationships.","growth":"Personal growth is gradual; celebrate small progress."},"shadow":"Abandoning efforts just before they bear fruit — or persisting long after they won''t.","misconceptions":["The card does not mean failure; it is a pause to evaluate growth."],"example":"Someone a year into building a small business draws the Seven of Pentacles: the card encourages reviewing results and adjusting strategy.","reflection":["What have I been cultivating?","Is it worth continuing to invest in?"],"memoryAid":"A farmer leans on his hoe watching coins grow: patience and assessment.","action":"Review one long-term effort: what''s working, what''s not, and what to change.","related":[{"id":"pentacles-08-eight","reason":"Diligent work and skill-building."},{"id":"major-09-the-hermit","reason":"Reflection and assessment."},{"id":"wands-03-three","reason":"Waiting for ventures to return."}],"numeral":"Seven","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('pentacles-08-eight', 'Eight of Pentacles', 'minor', 'pentacles', 8, '{"keywords":{"upright":["craftsmanship","dedication","skill development","diligence","mastery"],"reversed":["perfectionism","lack of focus","shortcuts","uninspired work"]},"traditional":"Waite gives work, employment, commission and craftsmanship — skill in craft and business, perhaps in the preparatory stage; reversed, voided ambition, vanity, cupidity and cunning.","symbols":[{"element":"Craftsman carving a pentacle","meaning":"Focused, repetitive practice."},{"element":"Finished pentacles displayed","meaning":"Progress made visible through effort."},{"element":"Distant town","meaning":"Withdrawing from distraction to focus on the work."},{"element":"Workbench","meaning":"The steady place of practice."}],"upright":"Dedicate yourself to improving your craft. Mastery comes from consistent, attentive practice.","reversed":"Perfectionism, shortcuts or boredom undermine the work. Reconnect with why it matters.","contexts":{"love":"Putting effort into the relationship; small, consistent acts matter.","career":"Training, skill-building and dedicated work.","finances":"Steady work builds financial security.","family":"Consistent effort strengthens family life.","growth":"Practise a skill daily; progress compounds."},"shadow":"Burying yourself in work to avoid other parts of life.","misconceptions":["The card is about deliberate practice, not drudgery."],"example":"Someone learning to play the guitar draws the Eight of Pentacles: the card encourages short, daily practice sessions.","reflection":["What skill am I committed to improving?","How can I practise with full attention?"],"memoryAid":"One coin carved at a time: the Eight of Pentacles is mastery through practice.","action":"Practise one skill for twenty focused minutes today.","related":[{"id":"pentacles-03-three","reason":"Skilled work in collaboration."},{"id":"major-01-the-magician","reason":"Skill and focused effort."},{"id":"pentacles-07-seven","reason":"Patient investment in growth."}],"numeral":"Eight","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('pentacles-09-nine', 'Nine of Pentacles', 'minor', 'pentacles', 9, '{"keywords":{"upright":["self-sufficiency","abundance","independence","luxury","discipline rewarded"],"reversed":["overwork","dependence","superficiality","financial setbacks"]},"traditional":"Waite gives prudence, safety, success, accomplishment, certitude and discernment; reversed, roguery, deception, voided projects and bad faith.","symbols":[{"element":"Elegant woman in a vineyard","meaning":"Enjoyment of the fruits of one''s labour."},{"element":"Hooded falcon","meaning":"Disciplined mind and controlled instincts."},{"element":"Grapevines and pentacles","meaning":"Abundance cultivated over time."},{"element":"Manor house","meaning":"Security and independence."},{"element":"Snail","meaning":"Slow, steady progress that led here."}],"upright":"Enjoy the abundance you''ve built through discipline. Independence and self-sufficiency are rewards to savour.","reversed":"Overwork, dependence or superficial comfort; reassess what true security means.","contexts":{"love":"Self-sufficiency within a relationship; enjoy your own company too.","career":"Independence and success earned through effort.","finances":"Financial independence and comfort.","family":"Enjoying the home you''ve created.","growth":"Self-discipline rewarded; savour your achievements."},"shadow":"Isolation disguised as independence.","misconceptions":["The card is about self-earned abundance, not luck."],"example":"Someone who paid off their debts draws the Nine of Pentacles: the card invites them to enjoy their hard-won independence.","reflection":["What have I built that I can enjoy?","How has discipline served me?"],"memoryAid":"A falcon on a gloved hand in a vineyard: the Nine of Pentacles savours the harvest.","action":"Enjoy something you''ve worked for, mindfully, today.","related":[{"id":"major-03-the-empress","reason":"Abundance and enjoyment of nature."},{"id":"cups-09-nine","reason":"Emotional satisfaction."},{"id":"pentacles-10-ten","reason":"Abundance extended to family and legacy."}],"numeral":"Nine","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('pentacles-10-ten', 'Ten of Pentacles', 'minor', 'pentacles', 10, '{"keywords":{"upright":["legacy","family wealth","long-term security","tradition","inheritance"],"reversed":["family conflict over money","instability","loss of legacy","breaking tradition"]},"traditional":"Waite gives gain, riches, family matters, archives, extraction and the abode of a family; reversed, chance, fatality, loss and robbery, as well as gift, dowry and pension.","symbols":[{"element":"Elder with two dogs","meaning":"Wisdom, loyalty and the passing of generations."},{"element":"Couple and child under the arch","meaning":"Family continuity."},{"element":"Ten pentacles in the Tree of Life pattern","meaning":"Material and spiritual wealth woven together."},{"element":"Castle estate","meaning":"Long-term security and legacy."}],"upright":"Long-term stability and legacy. Consider what you are building that will last beyond you.","reversed":"Conflicts over money or tradition, or instability in long-term plans. Revisit what legacy means.","contexts":{"love":"Long-term commitment and building a shared future.","career":"Established businesses, family enterprise or long-term career security.","finances":"Wealth-building, inheritance and long-term planning.","family":"Family ties, traditions and generational bonds.","growth":"Think about the legacy you want to leave."},"shadow":"Valuing family wealth or status over relationships.","misconceptions":["The card is not only about money; it is about lasting foundations and belonging."],"example":"Someone planning to buy a family home draws the Ten of Pentacles: the card reflects long-term security and legacy.","reflection":["What legacy am I building?","What traditions do I want to carry forward?"],"memoryAid":"Three generations beneath ten golden coins: the Ten of Pentacles is lasting legacy.","action":"Take one step toward a long-term goal — a savings plan, a family conversation, a record of family history.","related":[{"id":"cups-10-ten","reason":"Emotional fulfilment and family harmony."},{"id":"pentacles-01-ace","reason":"The seed that becomes a legacy."},{"id":"major-05-the-hierophant","reason":"Tradition and inheritance."}],"numeral":"Ten","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('pentacles-11-page', 'Page of Pentacles', 'minor', 'pentacles', 11, '{"keywords":{"upright":["study","ambition","diligence","new opportunity","practical learning"],"reversed":["procrastination","lack of progress","unrealistic goals","distraction"]},"traditional":"Waite gives application, study, scholarship and reflection, news and messages, rule and management; reversed, prodigality, dissipation and luxury, and unfavourable news.","symbols":[{"element":"Youth gazing at a pentacle","meaning":"Fascination with a practical goal or opportunity."},{"element":"Green meadow","meaning":"Fertile ground for new growth."},{"element":"Ploughed field","meaning":"Preparation and the work ahead."},{"element":"Grove of trees","meaning":"Steady, natural growth."}],"upright":"Study and practical ambition open new opportunities. As a role, the Page of Pentacles is the diligent student.","reversed":"Procrastination or unrealistic goals stall progress. Break plans into steps.","contexts":{"love":"A steady, sincere approach to love; slow but genuine.","career":"Training, education or a new practical opportunity.","finances":"Learning about money management; start saving.","family":"A studious young person, or learning new family skills.","growth":"Commit to learning something practical."},"shadow":"Studying endlessly without ever applying what you learn.","misconceptions":["The Page can be you at any age — it represents the learner''s mindset."],"example":"Someone thinking about a certification course draws the Page of Pentacles: the card encourages enrolling and studying steadily.","reflection":["What practical skill do I want to learn?","What is my first step?"],"memoryAid":"A youth studying a coin in a green field: the Page of Pentacles learns by doing.","action":"Spend thirty minutes learning a practical skill related to your goals.","related":[{"id":"pentacles-08-eight","reason":"Diligent practice."},{"id":"pentacles-01-ace","reason":"New material opportunity."},{"id":"swords-11-page","reason":"Another curious student, of ideas."}],"numeral":"Page","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('pentacles-12-knight', 'Knight of Pentacles', 'minor', 'pentacles', 12, '{"keywords":{"upright":["reliability","hard work","routine","patience","responsibility"],"reversed":["stagnation","boredom","laziness","perfectionism"]},"traditional":"Waite gives utility, serviceableness, interest, responsibility and rectitude on the normal and external plane; reversed, inertia, idleness, stagnation, discouragement and carelessness.","symbols":[{"element":"Still black horse","meaning":"Steady, unhurried progress."},{"element":"Pentacle held carefully","meaning":"Responsibility and attention to the task."},{"element":"Ploughed fields","meaning":"Methodical work and preparation."},{"element":"Oak sprigs","meaning":"Strength, endurance and growth over time."}],"upright":"Slow and steady wins. As a role, the Knight of Pentacles is dependable, methodical and committed.","reversed":"Routine may have become stagnation or perfectionism. Introduce small changes.","contexts":{"love":"Reliable, committed partnership; show love through consistent actions.","career":"Hard work and diligence pay off; stick with the plan.","finances":"Steady saving and responsible management.","family":"Dependable support; routines create stability.","growth":"Build habits patiently."},"shadow":"Refusing to change course out of habit.","misconceptions":["Slowness is not laziness here — it is steadiness."],"example":"Someone working toward a long-term savings goal draws the Knight of Pentacles: the card encourages consistent, patient effort.","reflection":["What routine supports my goals?","Where has routine become a rut?"],"memoryAid":"A knight on a still horse, holding his coin with care: steady and sure.","action":"Complete one routine task with full care and attention today.","related":[{"id":"pentacles-08-eight","reason":"Diligence and craftsmanship."},{"id":"major-04-the-emperor","reason":"Structure and responsibility."},{"id":"pentacles-14-king","reason":"Mature mastery of earth energy."}],"numeral":"Knight","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('pentacles-13-queen', 'Queen of Pentacles', 'minor', 'pentacles', 13, '{"keywords":{"upright":["nurturing","practicality","abundance","security","resourcefulness"],"reversed":["self-neglect","smothering","imbalance between work and home","materialism"]},"traditional":"Waite gives opulence, generosity, magnificence, security and liberty; reversed, evil, suspicion, suspense, fear and mistrust.","symbols":[{"element":"Pentacle cradled in the lap","meaning":"Nurturing care for resources and people."},{"element":"Bower of roses","meaning":"Abundance and comfort."},{"element":"Rabbit","meaning":"Fertility and grounded, earthy presence."},{"element":"Goat-head carvings","meaning":"Capricorn: practical ambition and resilience."}],"upright":"Provide practical care and create a nourishing environment. As a role, the Queen of Pentacles is warm, resourceful and grounded.","reversed":"Caring for others may leave you depleted, or work-home balance is off. Tend to your own needs.","contexts":{"love":"Nurturing, practical love; caring through actions.","career":"Balancing work and home; creating comfortable, productive environments.","finances":"Wise, generous money management.","family":"A nurturing, grounded presence who provides comfort.","growth":"Care for your body and your environment."},"shadow":"Measuring love by what is provided materially.","misconceptions":["The Queen of Pentacles is not only domestic; she manages resources skilfully in any field."],"example":"Someone setting up a home office draws the Queen of Pentacles: the card encourages creating a comfortable, nurturing space.","reflection":["How do I care for myself practically?","Where can I create more comfort?"],"memoryAid":"A queen in a rose bower cradling her coin: practical, nurturing abundance.","action":"Do one practical act of care for your home or body today.","related":[{"id":"major-03-the-empress","reason":"Nurturing abundance."},{"id":"pentacles-09-nine","reason":"Comfort and self-sufficiency."},{"id":"pentacles-14-king","reason":"Material mastery and success."}],"numeral":"Queen","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
insert into public.tarot_cards (id, name, arcana, suit, number, content, content_version) values ('pentacles-14-king', 'King of Pentacles', 'minor', 'pentacles', 14, '{"keywords":{"upright":["abundance","security","leadership","discipline","material success"],"reversed":["greed","stubbornness","materialism","poor financial decisions"]},"traditional":"Waite gives valour, realising intelligence, business and normal intellectual aptitude, sometimes mathematical gifts, and success in these paths; reversed, vice, weakness, perversity, corruption and peril.","symbols":[{"element":"Bull-carved throne","meaning":"Taurus: stability, persistence and material grounding."},{"element":"Grapevine robe","meaning":"Abundance that has grown around him."},{"element":"Pentacle and sceptre","meaning":"Mastery of the material world."},{"element":"Castle behind","meaning":"Security and achievement built over time."},{"element":"Armoured foot","meaning":"Discipline and protection beneath the comfort."}],"upright":"Lead with stability, generosity and practical wisdom. As a role, the King of Pentacles has built lasting success and shares it responsibly.","reversed":"Material focus may become greed or stubbornness. Balance success with generosity and flexibility.","contexts":{"love":"A stable, providing partner; security in the relationship.","career":"Business leadership, financial success and practical authority.","finances":"Wealth management and long-term financial security.","family":"A provider who creates stability for the family.","growth":"Mastering discipline and enjoying its rewards."},"shadow":"Measuring worth only by wealth and status.","misconceptions":["The King of Pentacles represents mastery and stewardship, not just wealth."],"example":"Someone deciding how to grow a profitable business draws the King of Pentacles: the card encourages steady, responsible leadership.","reflection":["How do I steward what I''ve built?","Where can I share my abundance?"],"memoryAid":"A king among grapevines on a bull throne: the King of Pentacles rules the harvest.","action":"Review your long-term financial plan and make one responsible adjustment.","related":[{"id":"major-04-the-emperor","reason":"Authority and stability."},{"id":"pentacles-10-ten","reason":"Legacy and long-term wealth."},{"id":"pentacles-13-queen","reason":"Nurturing, practical abundance."}],"numeral":"King","sources":[{"title":"The Pictorial Key to the Tarot","author":"Arthur Edward Waite","year":1911,"note":"Part III divinatory meanings, paraphrased in the `traditional` field. Public domain.","url":"https://sacred-texts.com/tarot/pkt/index.htm"},{"title":"The Daily Arcana card library","author":"The Daily Arcana editorial team","year":2026,"note":"Contemporary reflective interpretations, context meanings, exercises and memory aids written for this app. Modern practice, not historical tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set name = excluded.name, content = excluded.content, content_version = excluded.content_version, updated_at = now();
